// Package order defines the Go-side write-authority aggregate for the
// canonical Postgres sales.orders table. Each aggregate exposes a
// SINGLE constructor (`NewOrderFromProviderPayload`) that validates
// the normalised provider input against the wire schema BEFORE the
// UPSERT. See memory canonical-entity-shape-from-spec-not-wire +
// canonical-aggregate-strategy.
package entities

import (
	"errors"
	"fmt"
	"strings"
	"time"

	"template/api-go/internal/sync/objects"
	wire "template/contracts-go/wire"
	coreobjects "template/core-go/objects"
)

// Order is the canonical sales-order aggregate. Spec § BC4 Sales —
// composes OrderLine[] + OrderTransaction[] + 5 MonetaryAmount
// totals (per-money currency, no top-level scalar currency) + an
// optional shipping address + optional UTM tags +
// presentment/settlement money snapshots.
type Order struct {
	id                         coreobjects.ID
	platform                   wire.SalesPlatform
	externalID                 string
	externalCreatedAt          time.Time
	storeID                    string
	storeIntegrationID         string
	storeIntegrationExternalID string

	description         *string
	customerEmail       *string
	customerName        *string
	customerPhoneNumber *string
	shippingAddress     *objects.PostalAddress

	subtotal      objects.MonetaryAmount
	discountTotal objects.MonetaryAmount
	shippingTotal objects.MonetaryAmount
	taxTotal      objects.MonetaryAmount
	total         objects.MonetaryAmount

	presentmentMoney *objects.MonetaryAmount
	settlementMoney  *objects.MonetaryAmount

	paymentStatus  wire.PaymentStatus
	paymentMethod  wire.PaymentMethod
	paymentGateway wire.PaymentGateway

	lines        []OrderLine
	transactions []OrderTransaction

	cartToken *string
	utm       *objects.UtmTags
	isDraft   bool
	isManual  bool
}

// OrderInput is the normalised provider data the per-platform
// normaliser produces. The aggregate validates this before the
// UPSERT — anything that gets through has been recognised by the
// wire enum catalog + has the required scalar fields populated.
type OrderInput struct {
	Platform                   string
	ExternalID                 string
	ExternalCreatedAt          time.Time
	StoreID                    string
	StoreIntegrationID         string
	StoreIntegrationExternalID string

	Description         *string
	CustomerEmail       *string
	CustomerName        *string
	CustomerPhoneNumber *string
	ShippingAddress     *objects.PostalAddress

	Subtotal      objects.MonetaryAmount
	DiscountTotal objects.MonetaryAmount
	ShippingTotal objects.MonetaryAmount
	TaxTotal      objects.MonetaryAmount
	Total         objects.MonetaryAmount

	PresentmentMoney *objects.MonetaryAmount
	SettlementMoney  *objects.MonetaryAmount

	PaymentStatus  string
	PaymentMethod  string
	PaymentGateway string

	Lines        []OrderLine
	Transactions []OrderTransaction

	CartToken *string
	Utm       *objects.UtmTags
	IsDraft   bool
	IsManual  bool
}

var (
	ErrOrderMissingExternalID        = errors.New("order: externalId required")
	ErrOrderMissingStoreID           = errors.New("order: storeId required")
	ErrOrderMissingStoreIntegration  = errors.New("order: storeIntegrationId / storeIntegrationExternalId required")
	ErrOrderMissingExternalCreatedAt = errors.New("order: externalCreatedAt required")
	ErrOrderInvalidPlatform          = errors.New("order: invalid platform")
	ErrOrderInvalidPaymentStatus     = errors.New("order: invalid paymentStatus")
	ErrOrderInvalidPaymentMethod     = errors.New("order: invalid paymentMethod")
	ErrOrderInvalidPaymentGateway    = errors.New("order: invalid paymentGateway")
	ErrOrderMissingMoneyTotals       = errors.New("order: subtotal/discountTotal/shippingTotal/taxTotal/total all required")
)

// NewOrderFromProviderPayload validates + constructs the canonical
// Order aggregate. Lines and transactions are accepted as already-
// constructed (their own constructors enforced their invariants);
// here we just defensive-copy the slices.
func NewOrderFromProviderPayload(in OrderInput) (*Order, error) {
	if strings.TrimSpace(in.ExternalID) == "" {
		return nil, ErrOrderMissingExternalID
	}
	if strings.TrimSpace(in.StoreID) == "" {
		return nil, ErrOrderMissingStoreID
	}
	if strings.TrimSpace(in.StoreIntegrationID) == "" || strings.TrimSpace(in.StoreIntegrationExternalID) == "" {
		return nil, ErrOrderMissingStoreIntegration
	}
	if in.ExternalCreatedAt.IsZero() {
		return nil, ErrOrderMissingExternalCreatedAt
	}
	if in.Subtotal.IsZero() || in.DiscountTotal.IsZero() || in.ShippingTotal.IsZero() || in.TaxTotal.IsZero() || in.Total.IsZero() {
		// Spec: every monetary total carries its own currency; an
		// "absent" total is represented by a present-but-zero amount
		// in the right currency, not a zero-value MonetaryAmount.
		return nil, ErrOrderMissingMoneyTotals
	}

	platform, err := wire.ParseSalesPlatform(in.Platform)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrOrderInvalidPlatform, err)
	}
	paymentStatus, err := wire.ParsePaymentStatus(in.PaymentStatus)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrOrderInvalidPaymentStatus, err)
	}
	paymentMethod, err := wire.ParsePaymentMethod(in.PaymentMethod)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrOrderInvalidPaymentMethod, err)
	}
	paymentGateway, err := wire.ParsePaymentGateway(in.PaymentGateway)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrOrderInvalidPaymentGateway, err)
	}

	id, err := coreobjects.IDFromSeed("order", string(platform), in.ExternalID)
	if err != nil {
		return nil, fmt.Errorf("order: id derivation: %w", err)
	}

	return &Order{
		id:                         id,
		platform:                   platform,
		externalID:                 in.ExternalID,
		externalCreatedAt:          in.ExternalCreatedAt,
		storeID:                    in.StoreID,
		storeIntegrationID:         in.StoreIntegrationID,
		storeIntegrationExternalID: in.StoreIntegrationExternalID,
		description:                in.Description,
		customerEmail:              in.CustomerEmail,
		customerName:               in.CustomerName,
		customerPhoneNumber:        in.CustomerPhoneNumber,
		shippingAddress:            in.ShippingAddress,
		subtotal:                   in.Subtotal,
		discountTotal:              in.DiscountTotal,
		shippingTotal:              in.ShippingTotal,
		taxTotal:                   in.TaxTotal,
		total:                      in.Total,
		presentmentMoney:           in.PresentmentMoney,
		settlementMoney:            in.SettlementMoney,
		paymentStatus:              paymentStatus,
		paymentMethod:              paymentMethod,
		paymentGateway:             paymentGateway,
		lines:                      append([]OrderLine{}, in.Lines...),
		transactions:               append([]OrderTransaction{}, in.Transactions...),
		cartToken:                  in.CartToken,
		utm:                        in.Utm,
		isDraft:                    in.IsDraft,
		isManual:                   in.IsManual,
	}, nil
}

// Accessors — defensive copies for the slice fields so caller
// mutation doesn't leak into aggregate state.
func (o *Order) ID() coreobjects.ID                       { return o.id }
func (o *Order) Platform() wire.SalesPlatform             { return o.platform }
func (o *Order) ExternalID() string                       { return o.externalID }
func (o *Order) ExternalCreatedAt() time.Time             { return o.externalCreatedAt }
func (o *Order) StoreID() string                          { return o.storeID }
func (o *Order) StoreIntegrationID() string               { return o.storeIntegrationID }
func (o *Order) StoreIntegrationExternalID() string       { return o.storeIntegrationExternalID }
func (o *Order) Description() *string                     { return o.description }
func (o *Order) CustomerEmail() *string                   { return o.customerEmail }
func (o *Order) CustomerName() *string                    { return o.customerName }
func (o *Order) CustomerPhoneNumber() *string             { return o.customerPhoneNumber }
func (o *Order) ShippingAddress() *objects.PostalAddress  { return o.shippingAddress }
func (o *Order) Subtotal() objects.MonetaryAmount         { return o.subtotal }
func (o *Order) DiscountTotal() objects.MonetaryAmount    { return o.discountTotal }
func (o *Order) ShippingTotal() objects.MonetaryAmount    { return o.shippingTotal }
func (o *Order) TaxTotal() objects.MonetaryAmount         { return o.taxTotal }
func (o *Order) Total() objects.MonetaryAmount            { return o.total }
func (o *Order) PresentmentMoney() *objects.MonetaryAmount { return o.presentmentMoney }
func (o *Order) SettlementMoney() *objects.MonetaryAmount  { return o.settlementMoney }
func (o *Order) PaymentStatus() wire.PaymentStatus        { return o.paymentStatus }
func (o *Order) PaymentMethod() wire.PaymentMethod        { return o.paymentMethod }
func (o *Order) PaymentGateway() wire.PaymentGateway      { return o.paymentGateway }
func (o *Order) Lines() []OrderLine                       { return append([]OrderLine{}, o.lines...) }
func (o *Order) Transactions() []OrderTransaction         { return append([]OrderTransaction{}, o.transactions...) }
func (o *Order) CartToken() *string                       { return o.cartToken }
func (o *Order) Utm() *objects.UtmTags                    { return o.utm }
func (o *Order) IsDraft() bool                            { return o.isDraft }
func (o *Order) IsManual() bool                           { return o.isManual }

// Package product defines the Go-side write-authority aggregate for the
// canonical Postgres catalog.products table. See memory
// canonical-entity-shape-from-spec-not-wire + canonical-aggregate-strategy.
package entities

import (
	"errors"
	"fmt"
	"strings"
	"time"

	wire "template/contracts-go/wire"
	coreobjects "template/core-go/objects"
)

// Product is the canonical catalog-product aggregate. Spec § BC5
// Catalog: `id (deterministic), storeId, storeIntegrationId,
// externalId, title, handle, description?, pictureUrl?, status,
// collection?, tags, externalCreatedAt`.
//
// **Not on the spec aggregate** (intentional drops from the legacy
// shape): `lastSyncedAt`, `vendor`, `productType`,
// `storeIntegrationExternalId`. `tags` are merchant-owned (spec § BC5
// "Products and variants are write-locked except for merchant-owned
// `tags`") — Go writes the initial empty/imported set; subsequent
// AddProductTag / RemoveProductTag use cases mutate in the TS BC.
type Product struct {
	id                 coreobjects.ID
	platform           wire.SalesPlatform
	externalID         string
	storeID            string
	storeIntegrationID string

	title       string
	handle      string
	description *string
	pictureURL  *string
	status      wire.ProductStatus
	collection  *string

	externalCreatedAt time.Time
}

type ProductInput struct {
	Platform           string
	ExternalID         string
	StoreID            string
	StoreIntegrationID string

	Title       string
	Handle      string
	Description *string
	PictureURL  *string
	Status      string
	Collection  *string

	ExternalCreatedAt time.Time
}

var (
	ErrProductMissingExternalID         = errors.New("product: externalId required")
	ErrProductMissingStoreID            = errors.New("product: storeId required")
	ErrProductMissingStoreIntegrationID = errors.New("product: storeIntegrationId required")
	ErrProductMissingTitle              = errors.New("product: title required")
	ErrProductMissingHandle             = errors.New("product: handle required (normaliser must synthesise when provider omits)")
	ErrProductMissingExternalCreatedAt  = errors.New("product: externalCreatedAt required")
	ErrProductInvalidPlatform           = errors.New("product: invalid platform")
	ErrProductInvalidStatus             = errors.New("product: invalid status")
)

// NewProductFromProviderPayload validates + constructs the canonical
// Product. Tags are normalised: trimmed, empty-dropped — providers
// frequently emit blank entries from comma-split sources. nil Tags
// becomes an empty `[]string{}` (spec says `tags: string[]`, never
// missing).
func NewProductFromProviderPayload(in ProductInput) (*Product, error) {
	if strings.TrimSpace(in.ExternalID) == "" {
		return nil, ErrProductMissingExternalID
	}
	if strings.TrimSpace(in.StoreID) == "" {
		return nil, ErrProductMissingStoreID
	}
	if strings.TrimSpace(in.StoreIntegrationID) == "" {
		return nil, ErrProductMissingStoreIntegrationID
	}
	if strings.TrimSpace(in.Title) == "" {
		return nil, ErrProductMissingTitle
	}
	if strings.TrimSpace(in.Handle) == "" {
		return nil, ErrProductMissingHandle
	}
	if in.ExternalCreatedAt.IsZero() {
		return nil, ErrProductMissingExternalCreatedAt
	}

	platform, err := wire.ParseSalesPlatform(in.Platform)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrProductInvalidPlatform, err)
	}
	status, err := wire.ParseProductStatus(in.Status)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrProductInvalidStatus, err)
	}

	id, err := coreobjects.IDFromSeed("product", string(platform), in.ExternalID)
	if err != nil {
		return nil, fmt.Errorf("product: id derivation: %w", err)
	}

	return &Product{
		id:                 id,
		platform:           platform,
		externalID:         in.ExternalID,
		storeID:            in.StoreID,
		storeIntegrationID: in.StoreIntegrationID,
		title:              in.Title,
		handle:             in.Handle,
		description:        in.Description,
		pictureURL:         in.PictureURL,
		status:             status,
		collection:         in.Collection,
		externalCreatedAt:  in.ExternalCreatedAt,
	}, nil
}

func (p *Product) ID() coreobjects.ID           { return p.id }
func (p *Product) Platform() wire.SalesPlatform { return p.platform }
func (p *Product) ExternalID() string           { return p.externalID }
func (p *Product) StoreID() string              { return p.storeID }
func (p *Product) StoreIntegrationID() string   { return p.storeIntegrationID }
func (p *Product) Title() string                { return p.title }
func (p *Product) Handle() string               { return p.handle }
func (p *Product) Description() *string         { return p.description }
func (p *Product) PictureURL() *string          { return p.pictureURL }
func (p *Product) Status() wire.ProductStatus   { return p.status }
func (p *Product) Collection() *string          { return p.collection }
func (p *Product) ExternalCreatedAt() time.Time { return p.externalCreatedAt }

