	payload := wire.ProductUpdatedEvent{
		Name:                       wire.ProductUpdatedEventName,
		EntityID:                   p.ID().UUID().String(),
		OwnerID:                    p.StoreID(),
		Platform:                   p.Platform(),
		ExternalID:                 p.ExternalID(),
		StoreIntegrationExternalID: "", // dropped per spec § BC5; consumers join via catalog.store_integrations

