// Package order defines the Go-side write-authority aggregate for the
// canonical Postgres sales.orders table. Each aggregate exposes a
// SINGLE constructor (`NewOrderFromProviderPayload`) that validates
// the normalised provider input against the wire schema BEFORE the
// UPSERT. See memory canonical-entity-shape-from-spec-not-wire +
// canonical-aggregate-strategy.
package entities

import (
	"errors"
	"fmt"
	"strings"
	"time"

	"template/api-go/internal/sync/objects"
	wire "template/contracts-go/wire"
	coreobjects "template/core-go/objects"
)

// Order is the canonical sales-order aggregate. Spec § BC4 Sales —
// composes OrderLine[] + OrderTransaction[] + 5 MonetaryAmount
// totals (per-money currency, no top-level scalar currency) + an
// optional shipping address + optional UTM tags +
// presentment/settlement money snapshots.
type Order struct {
	id                         coreobjects.ID
	platform                   wire.SalesPlatform
	externalID                 string
	externalCreatedAt          time.Time
	storeID                    string
	storeIntegrationID         string
	storeIntegrationExternalID string

	description         *string
	customerEmail       *string
	customerName        *string
	customerPhoneNumber *string
	shippingAddress     *objects.PostalAddress

	subtotal      objects.MonetaryAmount
	discountTotal objects.MonetaryAmount
	shippingTotal objects.MonetaryAmount
	taxTotal      objects.MonetaryAmount
	total         objects.MonetaryAmount

	presentmentMoney *objects.MonetaryAmount
	settlementMoney  *objects.MonetaryAmount

	paymentStatus  wire.PaymentStatus
	paymentMethod  wire.PaymentMethod
	paymentGateway wire.PaymentGateway

	lines        []OrderLine
	transactions []OrderTransaction

	cartToken *string
	utm       *objects.UtmTags
	isDraft   bool
	isManual  bool
}

// OrderInput is the normalised provider data the per-platform
// normaliser produces. The aggregate validates this before the
// UPSERT — anything that gets through has been recognised by the
// wire enum catalog + has the required scalar fields populated.
type OrderInput struct {
	Platform                   string
	ExternalID                 string
	ExternalCreatedAt          time.Time
	StoreID                    string
	StoreIntegrationID         string
	StoreIntegrationExternalID string

	Description         *string
	CustomerEmail       *string
	CustomerName        *string
	CustomerPhoneNumber *string
	ShippingAddress     *objects.PostalAddress

	Subtotal      objects.MonetaryAmount
	DiscountTotal objects.MonetaryAmount
	ShippingTotal objects.MonetaryAmount
	TaxTotal      objects.MonetaryAmount
	Total         objects.MonetaryAmount

	PresentmentMoney *objects.MonetaryAmount
	SettlementMoney  *objects.MonetaryAmount

	PaymentStatus  string
	PaymentMethod  string
	PaymentGateway string

	Lines        []OrderLine
	Transactions []OrderTransaction

	CartToken *string
	Utm       *objects.UtmTags
	IsDraft   bool
	IsManual  bool
}

var (
	ErrOrderMissingExternalID        = errors.New("order: externalId required")
	ErrOrderMissingStoreID           = errors.New("order: storeId required")
	ErrOrderMissingStoreIntegration  = errors.New("order: storeIntegrationId / storeIntegrationExternalId required")
	ErrOrderMissingExternalCreatedAt = errors.New("order: externalCreatedAt required")
	ErrOrderInvalidPlatform          = errors.New("order: invalid platform")
	ErrOrderInvalidPaymentStatus     = errors.New("order: invalid paymentStatus")
	ErrOrderInvalidPaymentMethod     = errors.New("order: invalid paymentMethod")
	ErrOrderInvalidPaymentGateway    = errors.New("order: invalid paymentGateway")
	ErrOrderMissingMoneyTotals       = errors.New("order: subtotal/discountTotal/shippingTotal/taxTotal/total all required")
)

// NewOrderFromProviderPayload validates + constructs the canonical
// Order aggregate. Lines and transactions are accepted as already-
// constructed (their own constructors enforced their invariants);
// here we just defensive-copy the slices.
func NewOrderFromProviderPayload(in OrderInput) (*Order, error) {
	if strings.TrimSpace(in.ExternalID) == "" {
		return nil, ErrOrderMissingExternalID
	}
	if strings.TrimSpace(in.StoreID) == "" {
		return nil, ErrOrderMissingStoreID
	}
	if strings.TrimSpace(in.StoreIntegrationID) == "" || strings.TrimSpace(in.StoreIntegrationExternalID) == "" {
		return nil, ErrOrderMissingStoreIntegration
	}
	if in.ExternalCreatedAt.IsZero() {
		return nil, ErrOrderMissingExternalCreatedAt
	}
	if in.Subtotal.IsZero() || in.DiscountTotal.IsZero() || in.ShippingTotal.IsZero() || in.TaxTotal.IsZero() || in.Total.IsZero() {
		// Spec: every monetary total carries its own currency; an
		// "absent" total is represented by a present-but-zero amount
		// in the right currency, not a zero-value MonetaryAmount.
		return nil, ErrOrderMissingMoneyTotals
	}

	platform, err := wire.ParseSalesPlatform(in.Platform)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrOrderInvalidPlatform, err)
	}
	paymentStatus, err := wire.ParsePaymentStatus(in.PaymentStatus)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrOrderInvalidPaymentStatus, err)
	}
	paymentMethod, err := wire.ParsePaymentMethod(in.PaymentMethod)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrOrderInvalidPaymentMethod, err)
	}
	paymentGateway, err := wire.ParsePaymentGateway(in.PaymentGateway)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrOrderInvalidPaymentGateway, err)
	}

	id, err := coreobjects.IDFromSeed("order", string(platform), in.ExternalID)
	if err != nil {
		return nil, fmt.Errorf("order: id derivation: %w", err)
	}

	return &Order{
		id:                         id,
		platform:                   platform,
		externalID:                 in.ExternalID,
		externalCreatedAt:          in.ExternalCreatedAt,
		storeID:                    in.StoreID,
		storeIntegrationID:         in.StoreIntegrationID,
		storeIntegrationExternalID: in.StoreIntegrationExternalID,
		description:                in.Description,
		customerEmail:              in.CustomerEmail,
		customerName:               in.CustomerName,
		customerPhoneNumber:        in.CustomerPhoneNumber,
		shippingAddress:            in.ShippingAddress,
		subtotal:                   in.Subtotal,
		discountTotal:              in.DiscountTotal,
		shippingTotal:              in.ShippingTotal,
		taxTotal:                   in.TaxTotal,
		total:                      in.Total,
		presentmentMoney:           in.PresentmentMoney,
		settlementMoney:            in.SettlementMoney,
		paymentStatus:              paymentStatus,
		paymentMethod:              paymentMethod,
		paymentGateway:             paymentGateway,
		lines:                      append([]OrderLine{}, in.Lines...),
		transactions:               append([]OrderTransaction{}, in.Transactions...),
		cartToken:                  in.CartToken,
		utm:                        in.Utm,
		isDraft:                    in.IsDraft,
		isManual:                   in.IsManual,
	}, nil
}

