	discount          objects.MonetaryAmount
	tax               objects.MonetaryAmount
	totalPrice        objects.MonetaryAmount
}

type OrderLineInput struct {
	// Provider-side identity inputs. Combined with `platform` (passed
	// when the parent Order constructs the line) into the deterministic
	// `id`. `OrderExternalID` is the parent's externalId — added to
	// the hash seed so two lines with the same provider-line-id from
	// different orders don't collide on the same hashed id.
	Platform          string
	OrderExternalID   string
	ExternalID        string
	ProductExternalID string
	VariantExternalID string

	// Optional canonical id back-references — Go normalisers can fill
	// these once Product / ProductVariant rows are written; TS read
	// joins reach the same rows via (platform, externalId) lookups.
	ProductID *string
	VariantID *string

	Quantity int

	SubtotalPrice objects.MonetaryAmount
	Discount      objects.MonetaryAmount
	Tax           objects.MonetaryAmount
	TotalPrice    objects.MonetaryAmount
}

var (
	ErrLineMissingExternalID        = errors.New("orderLine: externalId required")
	ErrLineMissingProductExternalID = errors.New("orderLine: productExternalId required")
	ErrLineMissingVariantExternalID = errors.New("orderLine: variantExternalId required")
	ErrLineQuantityNegative         = errors.New("orderLine: quantity must be ≥ 0 (use 0 for refunded/voided lines)")
	ErrLineInvalidPlatform          = errors.New("orderLine: invalid platform")
	ErrLineMissingOrderExternalID   = errors.New("orderLine: orderExternalId required for id derivation")
)

func NewOrderLine(in OrderLineInput) (OrderLine, error) {
	if strings.TrimSpace(in.ExternalID) == "" {
		return OrderLine{}, ErrLineMissingExternalID
	}
	if strings.TrimSpace(in.OrderExternalID) == "" {
		return OrderLine{}, ErrLineMissingOrderExternalID
	}
	if strings.TrimSpace(in.ProductExternalID) == "" {
		return OrderLine{}, ErrLineMissingProductExternalID
	}
	if strings.TrimSpace(in.VariantExternalID) == "" {
		return OrderLine{}, ErrLineMissingVariantExternalID
	}
	if in.Quantity < 0 {
		return OrderLine{}, ErrLineQuantityNegative
	}

	platform, err := wire.ParseSalesPlatform(in.Platform)
	if err != nil {
		return OrderLine{}, fmt.Errorf("%w: %v", ErrLineInvalidPlatform, err)
	}

	id, err := coreobjects.IDFromSeed("order_line", string(platform), in.OrderExternalID, in.ExternalID)
	if err != nil {
		return OrderLine{}, fmt.Errorf("orderLine: id derivation: %w", err)
	}

	return OrderLine{
		id:                id,
		externalID:        in.ExternalID,
		productExternalID: in.ProductExternalID,
		variantExternalID: in.VariantExternalID,
		productID:         in.ProductID,
		variantID:         in.VariantID,
		quantity:          in.Quantity,
		subtotalPrice:     in.SubtotalPrice,
		discount:          in.Discount,
		tax:               in.Tax,
		totalPrice:        in.TotalPrice,
	}, nil
}

func (l OrderLine) ID() coreobjects.ID                    { return l.id }
func (l OrderLine) ExternalLineID() string                { return l.externalLineID }
func (l OrderLine) ProductExternalID() string             { return l.productExternalID }
func (l OrderLine) VariantExternalID() string             { return l.variantExternalID }
func (l OrderLine) ProductID() *string                    { return l.productID }
func (l OrderLine) VariantID() *string                    { return l.variantID }
func (l OrderLine) Quantity() int                         { return l.quantity }
func (l OrderLine) SubtotalPrice() objects.MonetaryAmount { return l.subtotalPrice }
func (l OrderLine) Discount() objects.MonetaryAmount      { return l.discount }
func (l OrderLine) Tax() objects.MonetaryAmount           { return l.tax }
func (l OrderLine) TotalPrice() objects.MonetaryAmount    { return l.totalPrice }

