// integration.shared.order.updated wire event. Moved here from the
// handler — the storage is the site that owns dual-write (upsert +
// outbox in one transaction).
//
// ownerID = storeId (consumers scope notifications + cache invalidations
// by store, not by aggregate).
//
// IsNew is set to false: Save does not know whether the row was
// inserted vs updated (UPSERT does not surface that).
func buildOrderUpdatedWireEvent(o *entities.Order) (types.DomainEventI, error) {
	entityJSON, err := json.Marshal(newOrderEntitySnapshot(o))
	if err != nil {
		return nil, fmt.Errorf("marshal order entity snapshot: %w", err)
	}

	payload := wire.OrderUpdatedEvent{
		Name:                       wire.OrderUpdatedEventName,
		EntityID:                   o.ID().UUID().String(),
		OwnerID:                    o.StoreID(),
		Platform:                   o.Platform(),
		ExternalID:                 o.ExternalID(),
		StoreIntegrationExternalID: o.StoreIntegrationExternalID(),
		PaymentStatus:              o.PaymentStatus(),
		TotalCents:                 o.Total().AmountCents(),
		Currency:                   o.Total().Currency(),
		IsNew:                      false, // see docstring
		CartToken:                  o.CartToken(),
		Entity:                     entityJSON,
	}

	return types.NewDomainEvent(
		wire.OrderUpdatedEventName,
		o.ID().UUID(),
		o.StoreID(),
		payload,
	), nil
