// jsonbValue returns an `any` suitable for the jsonb parameter slot —
// either the marshalled bytes or NULL when src is empty.
func jsonbValue(src any) (any, error) {
	if src == nil {
		return nil, nil
	}
	b, err := json.Marshal(src)
	if err != nil {
		return nil, err
	}
	return b, nil
}

func serialiseLines(lines []entities.OrderLine) (any, error) {
	if len(lines) == 0 {
		return []byte("[]"), nil
	}
	out := make([]orderLineJSON, 0, len(lines))
	for _, l := range lines {
		out = append(out, newOrderLineJSON(l))
	}
	return jsonbValue(out)
}

func serialiseTransactions(txs []entities.OrderTransaction) (any, error) {
	if len(txs) == 0 {
		return []byte("[]"), nil
	}
	out := make([]orderTransactionJSON, 0, len(txs))
	for _, t := range txs {
		out = append(out, newOrderTransactionJSON(t))
	}
	return jsonbValue(out)
}

func serialiseShippingAddress(a any) any {
	if a == nil {
		return nil
	}
	v, _ := jsonbValue(a)
	return v
}

func serialiseUtm(u any) any {
	if u == nil {
		return nil
	}
	v, _ := jsonbValue(u)
	return v
}

