package order

import (
	"context"
	"database/sql"
	"os"
	"testing"
	"time"

	_ "github.com/jackc/pgx/v5/stdlib"
	"template/api-go/internal/sync/entities"
	"template/api-go/internal/sync/objects"
	wire "template/contracts-go/wire"
	corerepos "template/core-go/repositories"
	"template/core-go/services/unitofwork"
)

func openTestDB(t *testing.T) *sql.DB {
	t.Helper()
	url := os.Getenv("DATABASE_URL")
	if url == "" {
		t.Skip("DATABASE_URL not set — skipping integration test")
	}
	db, err := sql.Open("pgx", url)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if err := db.PingContext(ctx); err != nil {
		_ = db.Close()
		t.Skipf("DB unreachable (Docker paused?) — skipping: %v", err)
	}
	return db
}

func mustMoneyPgTest(t *testing.T, cents int64, currency string) objects.MonetaryAmount {
	t.Helper()
	m, err := objects.NewMonetaryAmount(cents, currency)
	if err != nil {
		t.Fatalf("mustMoneyPgTest: %v", err)
	}
	return m
}

func buildTestOrder(t *testing.T, externalID, storeID, storeIntID, storeIntExtID string) *entities.Order {
	t.Helper()
	usd := func(cents int64) objects.MonetaryAmount {
		return mustMoneyPgTest(t, cents, "USD")
	}
	line, err := entities.NewOrderLine(entities.OrderLineInput{
		Platform:          string(wire.SalesPlatformSHOPIFY),
		OrderExternalID:   externalID,
		ExternalLineID:    externalID + "-line-1",
		ProductExternalID: "shopify_prod_1",
		VariantExternalID: "shopify_var_1",
		Quantity:          1,
		SubtotalPrice:     usd(5000),
		Discount:          usd(0),
		Tax:               usd(400),
		TotalPrice:        usd(5400),
	})
	if err != nil {
		t.Fatalf("NewOrderLine: %v", err)
	}
	o, err := entities.NewOrderFromProviderPayload(entities.OrderInput{
		Platform:                   string(wire.SalesPlatformSHOPIFY),
		ExternalID:                 externalID,
		ExternalCreatedAt:          time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC),
		StoreID:                    storeID,
		StoreIntegrationID:         storeIntID,
		StoreIntegrationExternalID: storeIntExtID,
		Subtotal:                   usd(5000),
		DiscountTotal:              usd(0),
		ShippingTotal:              usd(500),
		TaxTotal:                   usd(400),
		Total:                      usd(5900),
		PaymentStatus:              string(wire.PaymentStatusPAID),
		PaymentMethod:              string(wire.PaymentMethodCREDIT_CARD),
		PaymentGateway:             string(wire.PaymentGatewaySTRIPE),
		Lines:                      []entities.OrderLine{line},
	})
	if err != nil {
		t.Fatalf("NewOrderFromProviderPayload: %v", err)
	}
	return o
}

// TestPgOrderStorage_SaveDualWrite verifies that Save() inserts both the
// order rows into sales.orders AND the wire events into the outbox table
// within a single committed transaction.
func TestPgOrderStorage_SaveDualWrite(t *testing.T) {
	db := openTestDB(t)
	defer db.Close()

	uow := unitofwork.NewSQLUnitOfWork(db)
	eventRepo := corerepos.NewPgDomainEventRepository(db)
	storage := NewPgOrderStorage(db, uow, eventRepo)

	ctx := context.Background()

	storeID := "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"
	storeIntID := "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"
	storeIntExtID := "dual-write-test.myshopify.com"

	orderA := buildTestOrder(t, "pg-order-dual-write-1", storeID, storeIntID, storeIntExtID)
	orderB := buildTestOrder(t, "pg-order-dual-write-2", storeID, storeIntID, storeIntExtID)

	// Cleanup on exit so test is idempotent on a live DB.
	t.Cleanup(func() {
		_, _ = db.ExecContext(ctx, `DELETE FROM sales.orders WHERE id IN ($1, $2)`, orderA.ID().Value(), orderB.ID().Value())
		_, _ = db.ExecContext(ctx, `DELETE FROM shared.outbox WHERE owner_id = $1 AND name = $2`, storeID, wire.OrderUpdatedEventName)
		_, _ = db.ExecContext(ctx, `DELETE FROM shared.events WHERE owner_id = $1 AND name = $2`, storeID, wire.OrderUpdatedEventName)
	})

	// Save triggers the transactional dual-write.
	storage.Save([]*entities.Order{orderA, orderB})

	// Assert both order rows exist.
	for _, o := range []*entities.Order{orderA, orderB} {
		var count int
		err := db.QueryRowContext(ctx,
			`SELECT COUNT(*) FROM sales.orders WHERE id = $1`,
			o.ID().Value(),
		).Scan(&count)
		if err != nil {
			t.Fatalf("SELECT sales.orders id=%s: %v", o.ID().Value(), err)
		}
		if count != 1 {
			t.Errorf("sales.orders row count for id=%s = %d, want 1", o.ID().Value(), count)
		}
	}

	// Assert two wire events landed in the outbox.
	var outboxCount int
	err := db.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM shared.outbox WHERE owner_id = $1 AND name = $2`,
		storeID, wire.OrderUpdatedEventName,
	).Scan(&outboxCount)
	if err != nil {
		t.Fatalf("SELECT outbox: %v", err)
	}
	if outboxCount < 2 {
		t.Errorf("outbox event count = %d, want >= 2", outboxCount)
	}
}

// TestPgOrderStorage_NewConstructor verifies that the updated constructor
// compiles and accepts the new dependencies without panicking.
func TestPgOrderStorage_NewConstructor(t *testing.T) {
	db := openTestDB(t)
	defer db.Close()

	uow := unitofwork.NewSQLUnitOfWork(db)
	eventRepo := corerepos.NewPgDomainEventRepository(db)
	storage := NewPgOrderStorage(db, uow, eventRepo)

	if storage == nil {
		t.Fatal("NewPgOrderStorage returned nil")
	}
	if storage.InputChannel() == nil {
		t.Fatal("InputChannel() returned nil")
	}
}

