func (s *PgOrderStorage) Close() {
	close(s.inputCh)
}

// Start runs the accumulator select-loop. It blocks until ctx is done
// or the input channel is closed. Mirrors the reference Mongo shape.
func (s *PgOrderStorage) Start(ctx context.Context) error {
	ticker := time.NewTicker(flushInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			s.accumulator.Flush()
			return ctx.Err()
		case <-ticker.C:
			s.accumulator.Flush()
		case batch, ok := <-s.inputCh:
			if !ok {
				s.accumulator.Flush()
				return nil
			}
			s.accumulator.Add(batch)
			ticker.Reset(flushInterval)
		}
	}
}

// Save satisfies types.Saver[*entities.Order]. It is called by the
// Accumulator when a flush threshold is reached. All upserts + outbox
// inserts happen in a single UnitOfWork transaction.
func (s *PgOrderStorage) Save(batch []*entities.Order) {
	if len(batch) == 0 {
		return
	}

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	err := s.uow.Execute(ctx, func(ctx context.Context) error {
		for _, o := range batch {
			if err := s.upsert(ctx, o); err != nil {
				return fmt.Errorf("order upsert id=%s: %w", o.ID().Value(), err)
			}
			evt, err := buildOrderUpdatedWireEvent(o)
			if err != nil {
				return fmt.Errorf("order build wire event id=%s: %w", o.ID().Value(), err)
			}
			if err := s.events.Save(ctx, evt); err != nil {
				return fmt.Errorf("order save wire event id=%s: %w", o.ID().Value(), err)
			}
		}
		return nil
	})
	if err != nil {
		slog.Error("order storage Save failed", "batch_size", len(batch), "error", err)
	}
