	if p == nil {
		return fmt.Errorf("products upsert: nil product")
	}

	const stmt = `
		INSERT INTO catalog.products (
			id, store_integration_id, store_integration_external_id,
			platform, external_id, external_created_at,
			title, handle, description, image_url, status,
			vendor, product_type,
