	// schema even though the canonical Product aggregate dropped it
	// per spec (iter 279). Sourced from the platform-side natural
	// key — we forward the empty string since the canonical aggregate
	// doesn't carry it; consumers reading this column from the row
	// should join through catalog.store_integrations instead.
	db := s.txOrDB(ctx)
	_, err := db.ExecContext(ctx, stmt,
		p.ID().Value(), p.StoreIntegrationID(), "",
		string(p.Platform()), p.ExternalID(), p.ExternalCreatedAt(),
		p.Title(), p.Handle(), p.Description(), p.PictureURL(), string(p.Status()),
		p.Collection(),
	)
	return err
