// Package product defines the Go-side write-authority aggregate for the
// canonical Postgres catalog.products table. See memory
// canonical-entity-shape-from-spec-not-wire + canonical-aggregate-strategy.
package entities

import (
	"errors"
	"fmt"
	"strings"
	"time"

	wire "template/contracts-go/wire"
	coreobjects "template/core-go/objects"
)

// Product is the canonical catalog-product aggregate. Spec § BC5
// Catalog: `id (deterministic), storeIntegrationExternalId,
// externalId, title, handle, description?, pictureUrl?, status,
// collection?, tags, externalCreatedAt`. Tenancy is anchored on
// storeIntegrationExternalId — the stable provider-side handle (e.g.
// shop domain) that survives credential rotation, unlike the
// storeIntegrationId (which changes when the connection is re-created).
// The owning store is resolved via catalog.store_integrations.
//
// **Not on the spec aggregate** (intentional drops from the legacy
// shape): `lastSyncedAt`, `vendor`, `productType`,
// `storeIntegrationExternalId`. `tags` are merchant-owned (spec § BC5
// "Products and variants are write-locked except for merchant-owned
// `tags`") — Go writes the initial empty/imported set; subsequent
// AddProductTag / RemoveProductTag use cases mutate in the TS BC.
type Product struct {
	id                         coreobjects.ID
	platform                   wire.SalesPlatform
	externalID                 string
	storeIntegrationExternalID string

	title       string
	handle      string
	description *string
	pictureURL  *string
	status      wire.ProductStatus
	collection  *string

	externalCreatedAt time.Time
}

type ProductInput struct {
	Platform                   string
	ExternalID                 string
	StoreIntegrationExternalID string

	Title       string
	Handle      string
	Description *string
	PictureURL  *string
	Status      string
	Collection  *string

	ExternalCreatedAt time.Time
}

var (
	ErrProductMissingExternalID                 = errors.New("product: externalId required")
	ErrProductMissingStoreIntegrationExternalID = errors.New("product: storeIntegrationExternalId required")
	ErrProductMissingTitle                      = errors.New("product: title required")
	ErrProductMissingHandle                     = errors.New("product: handle required (normaliser must synthesise when provider omits)")
	ErrProductMissingExternalCreatedAt          = errors.New("product: externalCreatedAt required")
	ErrProductInvalidPlatform                   = errors.New("product: invalid platform")
	ErrProductInvalidStatus                     = errors.New("product: invalid status")
)

// NewProductFromProviderPayload validates + constructs the canonical
// Product. Tags are normalised: trimmed, empty-dropped — providers
// frequently emit blank entries from comma-split sources. nil Tags
// becomes an empty `[]string{}` (spec says `tags: string[]`, never
// missing).
func NewProductFromProviderPayload(in ProductInput) (*Product, error) {
	if strings.TrimSpace(in.ExternalID) == "" {
		return nil, ErrProductMissingExternalID
	}
	if strings.TrimSpace(in.StoreIntegrationExternalID) == "" {
		return nil, ErrProductMissingStoreIntegrationExternalID
	}
	if strings.TrimSpace(in.Title) == "" {
		return nil, ErrProductMissingTitle
	}
	if strings.TrimSpace(in.Handle) == "" {
		return nil, ErrProductMissingHandle
	}
	if in.ExternalCreatedAt.IsZero() {
		return nil, ErrProductMissingExternalCreatedAt
	}

	platform, err := wire.ParseSalesPlatform(in.Platform)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrProductInvalidPlatform, err)
	}
	status, err := wire.ParseProductStatus(in.Status)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrProductInvalidStatus, err)
	}

	id, err := coreobjects.IDFromSeed("product", string(platform), in.ExternalID)
	if err != nil {
		return nil, fmt.Errorf("product: id derivation: %w", err)
	}

	return &Product{
		id:                         id,
		platform:                   platform,
		externalID:                 in.ExternalID,
		storeIntegrationExternalID: in.StoreIntegrationExternalID,
		title:                      in.Title,
		handle:                     in.Handle,
		description:                in.Description,
		pictureURL:                 in.PictureURL,
		status:                     status,
		collection:                 in.Collection,
		externalCreatedAt:          in.ExternalCreatedAt,
	}, nil
}

func (p *Product) ID() coreobjects.ID                 { return p.id }
func (p *Product) Platform() wire.SalesPlatform       { return p.platform }
func (p *Product) ExternalID() string                 { return p.externalID }
func (p *Product) StoreIntegrationExternalID() string { return p.storeIntegrationExternalID }
func (p *Product) Title() string                      { return p.title }
func (p *Product) Handle() string                     { return p.handle }
func (p *Product) Description() *string               { return p.description }
func (p *Product) PictureURL() *string                { return p.pictureURL }
func (p *Product) Status() wire.ProductStatus         { return p.status }
func (p *Product) Collection() *string                { return p.collection }
func (p *Product) ExternalCreatedAt() time.Time       { return p.externalCreatedAt }

package entities

import (
	"errors"
	"testing"
	"time"

	"template/api-go/internal/sync/objects"
	wire "template/contracts-go/wire"
)

func validOrderInput(t *testing.T) OrderInput {
	line, err := NewOrderLine(validLineInput(t))
	if err != nil {
		t.Fatalf("line: %v", err)
	}
	tx, err := NewOrderTransaction(validTxInput(t))
	if err != nil {
		t.Fatalf("tx: %v", err)
	}
	return OrderInput{
		Platform:                   string(wire.SalesPlatformSHOPIFY),
		ExternalID:                 "shopify_order_1",
		ExternalCreatedAt:          time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC),
		StoreIntegrationID:         "00000000-0000-7000-8000-000000000002",
		StoreIntegrationExternalID: "acme.myshopify.com",
		Subtotal:                   mustMoney(t, 10000, wire.CurrencyCodeUSD),
		DiscountTotal:              mustMoney(t, 0, wire.CurrencyCodeUSD),
		ShippingTotal:              mustMoney(t, 500, wire.CurrencyCodeUSD),
		TaxTotal:                   mustMoney(t, 800, wire.CurrencyCodeUSD),
		Total:                      mustMoney(t, 11300, wire.CurrencyCodeUSD),
		PaymentStatus:              string(wire.PaymentStatusPAID),
		PaymentMethod:              string(wire.PaymentMethodCREDIT_CARD),
		PaymentGateway:             string(wire.PaymentGatewaySTRIPE),
		Lines:                      []OrderLine{line},
		Transactions:               []OrderTransaction{tx},
	}
}

func TestOrder_FromProviderPayload_Happy(t *testing.T) {
	o, err := NewOrderFromProviderPayload(validOrderInput(t))
	if err != nil {
		t.Fatal(err)
	}
	if o.Platform() != wire.SalesPlatformSHOPIFY {
		t.Errorf("Platform = %q", o.Platform())
	}
	if o.PaymentStatus() != wire.PaymentStatusPAID {
		t.Errorf("PaymentStatus = %q", o.PaymentStatus())
	}
	if o.PaymentMethod() != wire.PaymentMethodCREDIT_CARD {
		t.Errorf("PaymentMethod = %q", o.PaymentMethod())
	}
	if o.PaymentGateway() != wire.PaymentGatewaySTRIPE {
		t.Errorf("PaymentGateway = %q", o.PaymentGateway())
	}
	if o.Total().AmountCents() != 11300 {
		t.Errorf("Total = %d", o.Total().AmountCents())
	}
	if len(o.Lines()) != 1 {
		t.Errorf("Lines len = %d", len(o.Lines()))
	}
	if len(o.Transactions()) != 1 {
		t.Errorf("Transactions len = %d", len(o.Transactions()))
	}
	if o.ID().Value() == "" {
		t.Error("ID empty")
	}
	if o.IsDraft() || o.IsManual() {
		t.Error("default booleans should be false")
	}
}

func TestOrder_FromProviderPayload_DeterministicID(t *testing.T) {
	a, _ := NewOrderFromProviderPayload(validOrderInput(t))
	b, _ := NewOrderFromProviderPayload(validOrderInput(t))
	if a.ID().Value() != b.ID().Value() {
		t.Errorf("ID not deterministic: %s != %s", a.ID().Value(), b.ID().Value())
	}
}

func TestOrder_FromProviderPayload_OptionalFields(t *testing.T) {
	in := validOrderInput(t)
	desc := "Black Friday rush order"
	email := "buyer@example.com"
	name := "Alice"
	phone := "+1-555-0199"
	cart := "shopify_cart_abc"
	presentment := mustMoney(t, 11300, wire.CurrencyCodeUSD)
	settlement := mustMoney(t, 56500, wire.CurrencyCodeBRL)
	addr := &objects.PostalAddress{}
	utm := &objects.UtmTags{}

	in.Description = &desc
	in.CustomerEmail = &email
	in.CustomerName = &name
	in.CustomerPhoneNumber = &phone
	in.CartToken = &cart
	in.PresentmentMoney = &presentment
	in.SettlementMoney = &settlement
	in.ShippingAddress = addr
	in.Utm = utm
	in.IsDraft = true
	in.IsManual = true

	o, err := NewOrderFromProviderPayload(in)
	if err != nil {
		t.Fatal(err)
	}
	if o.Description() == nil || *o.Description() != desc {
		t.Errorf("Description = %v", o.Description())
	}
	if o.CartToken() == nil || *o.CartToken() != cart {
		t.Errorf("CartToken = %v", o.CartToken())
	}
	if o.PresentmentMoney() == nil || o.PresentmentMoney().AmountCents() != 11300 {
		t.Errorf("PresentmentMoney = %v", o.PresentmentMoney())
	}
	if o.SettlementMoney() == nil || o.SettlementMoney().Currency() != wire.CurrencyCodeBRL {
		t.Errorf("SettlementMoney = %v", o.SettlementMoney())
	}
	if o.ShippingAddress() == nil {
		t.Error("ShippingAddress nil")
	}
	if o.Utm() == nil {
		t.Error("Utm nil")
	}
	if !o.IsDraft() || !o.IsManual() {
		t.Error("draft/manual flags not preserved")
	}
}

func TestOrder_InvalidPaymentMethod(t *testing.T) {
	in := validOrderInput(t)
	in.PaymentMethod = "BARTER"
	_, err := NewOrderFromProviderPayload(in)
	if !errors.Is(err, ErrOrderInvalidPaymentMethod) {
		t.Errorf("expected ErrOrderInvalidPaymentMethod, got %v", err)
	}
}

func TestOrder_InvalidPaymentGateway(t *testing.T) {
	in := validOrderInput(t)
	in.PaymentGateway = "BITCOIN_GUY_DOWN_THE_STREET"
	_, err := NewOrderFromProviderPayload(in)
	if !errors.Is(err, ErrOrderInvalidPaymentGateway) {
		t.Errorf("expected ErrOrderInvalidPaymentGateway, got %v", err)
	}
}

func TestOrder_InvalidPaymentStatus(t *testing.T) {
	in := validOrderInput(t)
	in.PaymentStatus = "MAYBE_PAID"
	_, err := NewOrderFromProviderPayload(in)
	if !errors.Is(err, ErrOrderInvalidPaymentStatus) {
		t.Errorf("expected ErrOrderInvalidPaymentStatus, got %v", err)
	}
}

func TestOrder_MissingMoneyTotals(t *testing.T) {
	in := validOrderInput(t)
	in.TaxTotal = objects.MonetaryAmount{} // zero-value
	_, err := NewOrderFromProviderPayload(in)
	if !errors.Is(err, ErrOrderMissingMoneyTotals) {
		t.Errorf("expected ErrOrderMissingMoneyTotals, got %v", err)
	}
}

func TestOrder_MissingExternalID(t *testing.T) {
	in := validOrderInput(t)
	in.ExternalID = " "
	_, err := NewOrderFromProviderPayload(in)
	if !errors.Is(err, ErrOrderMissingExternalID) {
		t.Errorf("expected ErrOrderMissingExternalID, got %v", err)
	}
}

func TestOrder_MissingExternalCreatedAt(t *testing.T) {
	in := validOrderInput(t)
	in.ExternalCreatedAt = time.Time{}
	_, err := NewOrderFromProviderPayload(in)
	if !errors.Is(err, ErrOrderMissingExternalCreatedAt) {
		t.Errorf("expected ErrOrderMissingExternalCreatedAt, got %v", err)
	}
}

func TestOrder_SlicesIsolated(t *testing.T) {
	o, _ := NewOrderFromProviderPayload(validOrderInput(t))
	lines := o.Lines()
	lines[0] = OrderLine{}
	if o.Lines()[0].ExternalID() == "" {
		t.Error("Lines() returned a live slice; caller mutation leaked into aggregate state")
	}
	txs := o.Transactions()
	txs[0] = OrderTransaction{}
	if o.Transactions()[0].ExternalID() == "" {
		t.Error("Transactions() returned a live slice; caller mutation leaked into aggregate state")
	}
}

