	return ProductInput{
		Platform:           string(wire.SalesPlatformSHOPIFY),
		ExternalID:         "shopify_prod_1",
		StoreIntegrationID: "00000000-0000-7000-8000-000000000002",
		Title:              "Coffee Mug",
		Handle:             "coffee-mug",
		Status:             string(wire.ProductStatusACTIVE),
		ExternalCreatedAt:  time.Date(2026, 5, 1, 0, 0, 0, 0, time.UTC),
	}
}

func TestProduct_Happy(t *testing.T) {
	p, err := NewProductFromProviderPayload(validProductInput())
	if err != nil {
		t.Fatal(err)
	}
	if p.Title() != "Coffee Mug" {
		t.Errorf("Title = %q", p.Title())
	}
	if p.Handle() != "coffee-mug" {
		t.Errorf("Handle = %q", p.Handle())
	}
	if p.Status() != wire.ProductStatusACTIVE {
		t.Errorf("Status = %q", p.Status())
	}
	if p.ID().Value() == "" {
		t.Error("ID empty")
	}
}

func TestProduct_DeterministicID(t *testing.T) {
	a, _ := NewProductFromProviderPayload(validProductInput())
	b, _ := NewProductFromProviderPayload(validProductInput())
	if a.ID().Value() != b.ID().Value() {
		t.Errorf("ID not deterministic: %s != %s", a.ID().Value(), b.ID().Value())
	}
}

func TestProduct_OptionalFields(t *testing.T) {
	in := validProductInput()
	desc := "Ceramic mug, 12oz"
	pic := "https://example.com/mug.jpg"
	coll := "Drinkware"
	in.Description = &desc
	in.PictureURL = &pic
	in.Collection = &coll

	p, err := NewProductFromProviderPayload(in)
	if err != nil {
		t.Fatal(err)
	}
	if p.Description() == nil || *p.Description() != desc {
		t.Errorf("Description = %v", p.Description())
	}
	if p.PictureURL() == nil || *p.PictureURL() != pic {
		t.Errorf("PictureURL = %v", p.PictureURL())
