	"template/api-go/internal/sync/entities"
	"template/api-go/internal/sync/events"
	"template/api-go/internal/sync/objects"
	wire "template/contracts-go/wire"
	"template/core-go/types"
)

// fakeOrderStorage records every UpsertOrder call.
type fakeOrderStorage struct{ upserts []*entities.Order }

func (f *fakeOrderStorage) UpsertOrder(_ context.Context, o *entities.Order) error {
	f.upserts = append(f.upserts, o)
	return nil
}

// fakeOrderStorageChannel is a fake storage with an InputChannel — used by the
// new handler shape (Step 5). It does NOT expose UpsertOrder so there is no
// risk that the handler accidentally calls the upsert path directly.
type fakeOrderStorageChannel struct {
	ch chan []*entities.Order
}

func newFakeOrderStorageChannel() *fakeOrderStorageChannel {
	return &fakeOrderStorageChannel{ch: make(chan []*entities.Order, 8)}
}

func (f *fakeOrderStorageChannel) InputChannel() chan<- []*entities.Order {
	return f.ch
}

// fakeEventRepo records every Save / SaveAll call.
type fakeEventRepo struct{ saved []types.DomainEventI }

func (f *fakeEventRepo) Save(_ context.Context, e types.DomainEventI) error {
	f.saved = append(f.saved, e)
	return nil
}
func (f *fakeEventRepo) SaveAll(_ context.Context, es []types.DomainEventI) error {
	f.saved = append(f.saved, es...)
	return nil
}

// buildTestOrderInput returns a minimal valid OrderInput for use in handler tests.
func buildTestOrderInput(t *testing.T) entities.OrderInput {
	t.Helper()
	usd := func(cents int64) objects.MonetaryAmount {
		m, err := objects.NewMonetaryAmount(cents, string(wire.CurrencyCodeUSD))
		if err != nil {
			t.Fatalf("NewMonetaryAmount: %v", err)
		}
		return m
	}
	line, err := entities.NewOrderLine(entities.OrderLineInput{
		Platform:          string(wire.SalesPlatformSHOPIFY),
		OrderExternalID:   "shopify_order_1",
		ExternalID:        "shopify_line_1",
		ProductExternalID: "shopify_prod_1",
		VariantExternalID: "shopify_var_1",
		Quantity:          1,
		SubtotalPrice:     usd(5000),
		Discount:          usd(0),
		Tax:               usd(400),
		TotalPrice:        usd(5400),
	})
	if err != nil {
		t.Fatalf("NewOrderLine: %v", err)
	}
	return entities.OrderInput{
		Platform:                   string(wire.SalesPlatformSHOPIFY),
		ExternalID:                 "shopify_order_1",
		ExternalCreatedAt:          time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC),
		StoreIntegrationID:         "00000000-0000-7000-8000-000000000002",
		StoreIntegrationExternalID: "acme.myshopify.com",
		Subtotal:                   usd(5000),
		DiscountTotal:              usd(0),
		ShippingTotal:              usd(500),
		TaxTotal:                   usd(400),
		Total:                      usd(5900),
		PaymentStatus:              string(wire.PaymentStatusPAID),
		PaymentMethod:              string(wire.PaymentMethodCREDIT_CARD),
		PaymentGateway:             string(wire.PaymentGatewaySTRIPE),
		Lines:                      []entities.OrderLine{line},
	}
}

// TestOrderHandler_EnqueuesConstructedOrder verifies that the new handler:
//   - constructs the Order aggregate from the event payload,
//   - enqueues exactly one []*entities.Order batch of length 1 on the storage
//     input channel with StoreIntegrationID matching the event payload,
//   - does NOT call any upsert / DB method directly.
func TestOrderHandler_EnqueuesConstructedOrder(t *testing.T) {
	storage := newFakeOrderStorageChannel()
	h := NewOrderUpdatedHandler(storage)

	input := buildTestOrderInput(t)
	evt := events.NewExternalOrderUpdated(input, "00000000-0000-7000-8000-000000000001")

	if err := h.Handle(context.Background(), evt); err != nil {
		t.Fatalf("Handle: %v", err)
	}

	// Expect exactly one batch on the channel.
	select {
	case batch := <-storage.ch:
		if len(batch) != 1 {
			t.Fatalf("batch len = %d, want 1", len(batch))
		}
		if batch[0].StoreIntegrationID() != "00000000-0000-7000-8000-000000000002" {
			t.Errorf("StoreIntegrationID = %q, want 00000000-0000-7000-8000-000000000002", batch[0].StoreIntegrationID())
		}
	default:
		t.Fatal("no batch enqueued on InputChannel")
	}
}

func TestOrderUpdatedHandler_EventName(t *testing.T) {
	h := NewOrderUpdatedHandler(newFakeOrderStorageChannel())
	if h.EventName() != events.ExternalOrderUpdatedEventName {
		t.Fatalf("EventName = %q, want %q", h.EventName(), events.ExternalOrderUpdatedEventName)
	}
}

func TestOrderUpdatedHandler_WrongEventTypeError(t *testing.T) {
	h := NewOrderUpdatedHandler(newFakeOrderStorageChannel())
	// Pass a wrong event type — Handle must return an error.
	other := types.NewDomainEvent("some.other.event", [16]byte{}, "", struct{}{})
	if err := h.Handle(context.Background(), other); err == nil {
		t.Error("expected error for wrong event type, got nil")
	}
}

