		t.Fatalf("mustMoneyPgTest: %v", err)
	}
	return m
}

func buildTestOrder(t *testing.T, externalID, storeIntExtID string) *entities.Order {
	t.Helper()
	usd := func(cents int64) objects.MonetaryAmount {
		return mustMoneyPgTest(t, cents, "USD")
	}
	line, err := entities.NewOrderLine(entities.OrderLineInput{
		Platform:          string(wire.SalesPlatformSHOPIFY),
		OrderExternalID:   externalID,
		ExternalID:        externalID + "-line-1",
		ProductExternalID: "shopify_prod_1",
		VariantExternalID: "shopify_var_1",
		Quantity:          1,
		SubtotalPrice:     usd(5000),
		Discount:          usd(0),
		Tax:               usd(400),
		TotalPrice:        usd(5400),
	})
	if err != nil {
		t.Fatalf("NewOrderLine: %v", err)
	}
	o, err := entities.NewOrderFromProviderPayload(entities.OrderInput{
		Platform:                   string(wire.SalesPlatformSHOPIFY),
		ExternalID:                 externalID,
		ExternalCreatedAt:          time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC),
		StoreIntegrationExternalID: storeIntExtID,
		Subtotal:                   usd(5000),
		DiscountTotal:              usd(0),
		ShippingTotal:              usd(500),
		TaxTotal:                   usd(400),
		Total:                      usd(5900),
		PaymentStatus:              string(wire.PaymentStatusPAID),
		PaymentMethod:              string(wire.PaymentMethodCREDIT_CARD),
		PaymentGateway:             string(wire.PaymentGatewaySTRIPE),
		Lines:                      []entities.OrderLine{line},
	})
	if err != nil {
		t.Fatalf("NewOrderFromProviderPayload: %v", err)
	}
	return o
}

