		// SINGLE = one cost across all variants; MULTIPLE = per-variant.
		costType: text('cost_type').notNull(),

		// Time-effective option array, stored inline as jsonb. Each
		// option carries: { id, currency, country?, startDate, endDate?,
		// items: [{id, variantIds, quantity, quantityModifier,
		// unitCost, variantsHash}] }.
		// Inlined (vs the original product_cost_options child table)
		// because reads always pull the full document; the child-table
		// shape required cascade writes + N+1 reads for no actual
		// normalization benefit.
		options: jsonb('options').notNull().default([]),

		// Soft-delete timestamp. List queries filter by `deleted_at IS NULL`.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Partial unique — only enforce on live rows so a re-created cost
		// for the same (storeId, productId) after soft-delete doesn't
		// collide with the historical row.
		storeProductUnq: uniqueIndex('product_costs_store_product_unq').on(t.storeId, t.productId).where(sql`${t.deletedAt} IS NULL`),
