import { sql } from 'drizzle-orm'

/**
 * `catalog` is BK Dash's BC5 Catalog schema.
 *
 * Two ownership models live in the same schema:
 *   - `products` + `variants` are **Go-owned** canonical projections,
 *     written via UPSERT by go-worker every time a provider catalog
 *     sync lands. Deterministic UUIDv5 PK + unique (platform,
 *     external_id) lets the (xmax = 0) is_new detection ride alongside.
 *   - `product_costs` (+ `product_cost_options`) is **TS-owned** —
 *     merchant-entered cost data, no provider source. Joined to
 *     products at analytics-query time to derive profit margin.
 */
export const catalogSchema = pgSchema('catalog')

export const products = catalogSchema.table(
	'products',
	{
		id: uuid('id').primaryKey(),

		// Tenancy is anchored on storeIntegrationExternalId — the stable
		// provider-side handle (e.g. shop domain) that survives credential
		// rotation, unlike the storeIntegrationId connection row (dropped).
		// The owning store is reached via catalog.store_integrations.
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		platform: text('platform').notNull(),
		externalId: text('external_id').notNull(),

		// Provider-side identifiers + presentation.
		title: text('title').notNull(),
		handle: text('handle'),
		description: text('description'),
		vendor: text('vendor'),
		productType: text('product_type'),
		imageUrl: text('image_url'),

		// Status enum value from spec ProductStatus (ACTIVE/ARCHIVED/DRAFT)
		// — stored as text rather than pgEnum so we don't lock the
		// migration to one snapshot of the enum.
		status: text('status').notNull(),

		// Aggregated price range across all variants — cheap to denormalize
		// here so list views don't fan out to variant rows.
		minPriceCents: bigint('min_price_cents', { mode: 'bigint' }),
		maxPriceCents: bigint('max_price_cents', { mode: 'bigint' }),
		currency: text('currency'),

		externalCreatedAt: timestamp('external_created_at', { withTimezone: true }).notNull(),

		// Audit / optimistic concurrency.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		platformExternalIdUnq: uniqueIndex('products_platform_external_id_unq').on(t.platform, t.externalId),
		storeIntegrationIdx: index('products_store_integration_id_idx').on(t.storeIntegrationId),
		statusIdx: index('products_status_idx').on(t.status),
	}),
)

/**
 * TS-owned merchant overlay on canonical Product (SPEC-10). Carries
 * fields the merchant edits without the Go sync pipeline overwriting:
 * starts with `tags`, future extensions go here (custom descriptions, etc.).
 * Unique on (product_id, store_id) — 1:1 with Product per Store.
 */
export const productOverrides = catalogSchema.table(
	'product_overrides',
	{
		id: uuid('id').primaryKey(),
		productId: uuid('product_id').notNull(),
		storeId: uuid('store_id').notNull(),

		// Merchant-curated tag list (moved off canonical Product).
		tags: jsonb('tags').notNull().default(sql`'[]'::jsonb`),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		productStoreUnq: uniqueIndex('product_overrides_product_id_store_id_unq').on(t.productId, t.storeId),
		storeIdx: index('product_overrides_store_id_idx').on(t.storeId),
	}),
)

export const variants = catalogSchema.table(
	'variants',
	{
		id: uuid('id').primaryKey(),

		// Parent product. Intentionally NO FK reference (Go writes variants
		// concurrently with products during a backfill; a strict FK would
		// require ordering writes by parent-then-child which `sqlc` doesn't
		// naturally express). Drizzle queries JOIN by product_id explicitly.
		productId: uuid('product_id').notNull(),

