import { injectable } from 'tsyringe-neo'
import { eq } from 'drizzle-orm'
import { DrizzleClient } from '@bk-dash/core-typescript'
import { orders } from '@bk-dash/contracts/db'
import { OrderQueryService, OrderQueryDTOSchema, type OrderQueryDTO } from './OrderQueryService'

type OrderRow = typeof orders.$inferSelect

@injectable()
export class DrizzleOrderQueryService extends OrderQueryService {
	constructor(private readonly db: DrizzleClient) {
		super()
	}

	async findById(orderId: string): Promise<OrderQueryDTO | null> {
		const rows = await this.db.select().from(orders).where(eq(orders.id, orderId)).limit(1)
		if (rows.length === 0) return null
		return this.mapRow(rows[0]!)
	}

	async findByStore(storeId: string): Promise<OrderQueryDTO[]> {
		const rows = await this.db.select().from(orders).where(eq(orders.storeId, storeId))
		return rows.map(r => this.mapRow(r))
	}

	private mapRow(row: OrderRow): OrderQueryDTO {
		const rawLines = (row.lines as { id?: string; productId?: string; variantId?: string; quantity?: number }[]) ?? []
		return OrderQueryDTOSchema.parse({
			id: row.id,
			storeId: row.storeId,
			storeIntegrationExternalId: row.storeIntegrationExternalId,
			externalCreatedAt: row.externalCreatedAt,
			lines: rawLines.map(l => ({
				id: l.id ?? '',
				productId: l.productId,
				variantId: l.variantId,
				quantity: l.quantity ?? 0,
			})),
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { OrderQueryService, type OrderQueryDTO } from './OrderQueryService'

@injectable()
export class MockOrderQueryService extends OrderQueryService {
	/** Seed orders the next find calls return. */
	nextOrders: OrderQueryDTO[] = []

	async findById(orderId: string): Promise<OrderQueryDTO | null> {
		return this.nextOrders.find(o => o.id === orderId) ?? null
	}

	async findByStore(storeId: string): Promise<OrderQueryDTO[]> {
		return this.nextOrders.filter(o => o.storeId === storeId)
	}
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DrizzleClient, Id } from '@bk-dash/core-typescript'
import { orders } from '@bk-dash/contracts/db'
import { DrizzleOrderQueryService } from './DrizzleOrderQueryService'

const STORE_ID = testId('store', '1')
const SI_EXTERNAL = 'acme.myshopify.com'
const PLATFORM = 'SHOPIFY'
const ORDER_EXTERNAL_1 = 'shopify_order_1'
const ORDER_EXTERNAL_2 = 'shopify_order_2'
const ORDER_ID_1 = Id.fromSeed('order', PLATFORM, ORDER_EXTERNAL_1).value
const ORDER_ID_2 = Id.fromSeed('order', PLATFORM, ORDER_EXTERNAL_2).value

const baseOrder = {
	storeId: STORE_ID,
	storeIntegrationId: testId('store-integration', '1'),
	storeIntegrationExternalId: SI_EXTERNAL,
	platform: PLATFORM,
	externalCreatedAt: new Date('2026-05-01T10:00:00Z'),
	subtotalCents: 0n,
	discountTotalCents: 0n,
	shippingTotalCents: 0n,
	taxTotalCents: 0n,
	totalCents: 1000n,
	totalCurrency: 'USD',
	paymentStatus: 'PAID',
	paymentMethod: 'CREDIT_CARD',
	paymentGateway: 'STRIPE',
	transactions: [],
}

describe('DrizzleOrderQueryService', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let service: DrizzleOrderQueryService
	let db: any

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		db = testBed.resolve(DrizzleClient)
	})
	beforeEach(async () => {
		await testBed.reset()
		service = testBed.resolve(DrizzleOrderQueryService)
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('findById returns null when order does not exist', async () => {
		const result = await service.findById('00000000-0000-0000-0000-000000000000')
		expect(result).toBeNull()
	})

	it('findById returns an order with its lines', async () => {
		const lines = [{ id: 'line-1', productId: 'prod-a', variantId: 'var-a', quantity: 2 }]
		await db.insert(orders).values({ id: ORDER_ID_1, externalId: ORDER_EXTERNAL_1, lines, ...baseOrder })
		const result = await service.findById(ORDER_ID_1)
		expect(result).not.toBeNull()
		expect(result!.id).toBe(ORDER_ID_1)
		expect(result!.storeId).toBe(STORE_ID)
		expect(result!.storeIntegrationExternalId).toBe(SI_EXTERNAL)
		expect(result!.lines).toHaveLength(1)
		expect(result!.lines[0]!.id).toBe('line-1')
		expect(result!.lines[0]!.quantity).toBe(2)
	})

	it('findByStore returns all orders for a store', async () => {
		const lines = [{ id: 'line-1', productId: 'prod-a', variantId: 'var-a', quantity: 1 }]
		await db.insert(orders).values([
			{ id: ORDER_ID_1, externalId: ORDER_EXTERNAL_1, lines, ...baseOrder },
			{ id: ORDER_ID_2, externalId: ORDER_EXTERNAL_2, lines: [], ...baseOrder },
		])
		const results = await service.findByStore(STORE_ID)
		expect(results).toHaveLength(2)
		const ids = results.map(o => o.id)
		expect(ids).toContain(ORDER_ID_1)
		expect(ids).toContain(ORDER_ID_2)
	})

	it('findByStore returns empty array when store has no orders', async () => {
		const results = await service.findByStore(STORE_ID)
		expect(results).toEqual([])
	})
})

import { injectable } from 'tsyringe-neo'
import { eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { orders } from '@bk-dash/contracts/db'
import { OrderSamplingService } from '../../tenancy/services/OrderSamplingService'

/**
 * Real implementation of Tenancy's cross-BC OrderSamplingService
 * port. Sales owns `sales.orders` — this adapter lives inside the
 * Sales BC and is bound via sales/registry.ts (overrides tenancy's
 * Mock binding via load order: tenancy registers first; sales's
 * later entry wins).
 *
 * `hasOrdersForStore` is used by Tenancy's UpdateStorePreferences
 * (C14) to gate the REPORTING_CURRENCY_LOCKED invariant — once a
 * store has any orders, currency cannot be re-pointed because
 * historical analytics rollups would lose their rate context.
 *
 * Single-row LIMIT 1 SELECT is the cheap "exists" check; no need to
 * count.
 */
@injectable()
export class SalesOrderSamplingService extends OrderSamplingService {
	constructor(private db: DrizzleClient) {
		super()
	}

	async hasOrdersForStore(storeId: string): Promise<boolean> {
		const result = await tryCatchAsync(async () => {
			const rows = await this.db.select({ id: orders.id }).from(orders).where(eq(orders.storeId, storeId)).limit(1)
			return rows.length > 0
		})
		if (!result.success) throw result.error
		return result.data
	}
}

import { injectable } from 'tsyringe-neo'
import { ProductQueryService, type ProductQueryDTO, type ResolvedProductWithVariants } from './ProductQueryService'

@injectable()
export class MockProductQueryService extends ProductQueryService {
	/** Seed products the next find calls return. */
	nextProducts: ProductQueryDTO[] = []

	async findById(productId: string): Promise<ProductQueryDTO | null> {
		return this.nextProducts.find(p => p.id === productId) ?? null
	}

	async findByIds(productIds: string[]): Promise<ProductQueryDTO[]> {
		return this.nextProducts.filter(p => productIds.includes(p.id))
	}

	/** Seed the rows the next resolveProductsWithVariantsByHandles call returns. */
	nextResolved: ResolvedProductWithVariants[] = []

	async resolveProductsWithVariantsByHandles(_storeIntegrationId: string, handles: string[]): Promise<ResolvedProductWithVariants[]> {
		return this.nextResolved.filter(p => handles.includes(p.handle))
	}
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DrizzleClient, Id } from '@bk-dash/core-typescript'
import { ProductStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { products, productOverrides, variants } from '@bk-dash/contracts/db'
import { DrizzleProductQueryService } from './DrizzleProductQueryService'

const STORE_ID = testId('store', '1')
const STORE_INTEGRATION_ID = testId('store_integration', '1')
const PRODUCT_ID = Id.fromSeed('product', 'SHOPIFY', 'prod-1').value
const PRODUCT_ID_2 = Id.fromSeed('product', 'SHOPIFY', 'prod-2').value

describe('DrizzleProductQueryService', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let service: DrizzleProductQueryService
	let db: any

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		db = testBed.resolve(DrizzleClient)
	})
	beforeEach(async () => {
		await testBed.reset()
		service = testBed.resolve(DrizzleProductQueryService)
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedProduct(id: string, externalId: string, overrideTags?: string[]): Promise<void> {
		await db.insert(products).values({
			id,
			storeId: STORE_ID,
			storeIntegrationId: STORE_INTEGRATION_ID,
			storeIntegrationExternalId: 'acme.myshopify.com',
			platform: 'SHOPIFY',
			externalId,
			title: `Product ${externalId}`,
			handle: `product-${externalId}`,
			status: 'ACTIVE',
			externalCreatedAt: new Date('2026-01-01T00:00:00Z'),
		})
		if (overrideTags !== undefined) {
			await db.insert(productOverrides).values({
				id: Id.fromSeed('product_override', id, STORE_ID).value,
				productId: id,
				storeId: STORE_ID,
				tags: JSON.stringify(overrideTags),
			})
		}
	}

	it('findById returns null when product does not exist', async () => {
		const result = await service.findById('00000000-0000-0000-0000-000000000000')
		expect(result).toBeNull()
	})

	it('findById returns the product with its tags from productOverrides', async () => {
		await seedProduct(PRODUCT_ID, 'prod-1', ['bestseller'])
		const result = await service.findById(PRODUCT_ID)
		expect(result).not.toBeNull()
		expect(result!.id).toBe(PRODUCT_ID)
		expect(result!.storeId).toBe(STORE_ID)
		expect(result!.title).toBe('Product prod-1')
		expect(result!.handle).toBe('product-prod-1')
		expect(result!.status).toBe(ProductStatus.ACTIVE)
		expect(result!.tags).toEqual(['bestseller'])
	})

	it('findById returns empty tags when no override exists', async () => {
		await seedProduct(PRODUCT_ID, 'prod-1')
		const result = await service.findById(PRODUCT_ID)
		expect(result!.tags).toEqual([])
	})

	it('findByIds returns all matching products', async () => {
		await seedProduct(PRODUCT_ID, 'prod-1', ['a'])
		await seedProduct(PRODUCT_ID_2, 'prod-2', ['b'])
		const results = await service.findByIds([PRODUCT_ID, PRODUCT_ID_2])
		expect(results).toHaveLength(2)
		const ids = results.map(p => p.id)
		expect(ids).toContain(PRODUCT_ID)
		expect(ids).toContain(PRODUCT_ID_2)
	})

	it('findByIds with empty array returns empty array', async () => {
		const results = await service.findByIds([])
		expect(results).toEqual([])
	})

	async function seedVariant(id: string, productId: string, externalId: string, title: string): Promise<void> {
		await db.insert(variants).values({
			id,
			productId,
			storeIntegrationId: STORE_INTEGRATION_ID,
			storeIntegrationExternalId: 'acme.myshopify.com',
			platform: 'SHOPIFY',
			externalId,
			productExternalId: 'prod-1',
			title,
			status: 'ACTIVE',
			externalCreatedAt: new Date('2026-01-01T00:00:00Z'),
		})
	}

	it('resolveProductsWithVariantsByHandles maps handle → product + variants by title', async () => {
		await seedProduct(PRODUCT_ID, 'prod-1')
		await seedVariant(Id.fromSeed('variant', 'SHOPIFY', 'v1').value, PRODUCT_ID, 'v1', 'Black / M')
		await seedVariant(Id.fromSeed('variant', 'SHOPIFY', 'v2').value, PRODUCT_ID, 'v2', 'Black / L')

		const result = await service.resolveProductsWithVariantsByHandles(STORE_INTEGRATION_ID, ['product-prod-1'])
		expect(result).toHaveLength(1)
		expect(result[0]!.productId).toBe(PRODUCT_ID)
		expect(result[0]!.handle).toBe('product-prod-1')
		const titles = result[0]!.variants.map(v => v.title).sort()
		expect(titles).toEqual(['Black / L', 'Black / M'])
	})

	it('resolveProductsWithVariantsByHandles returns [] for unknown handles + [] input', async () => {
		expect(await service.resolveProductsWithVariantsByHandles(STORE_INTEGRATION_ID, [])).toEqual([])
		expect(await service.resolveProductsWithVariantsByHandles(STORE_INTEGRATION_ID, ['nope'])).toEqual([])
	})
})

import { injectable } from 'tsyringe-neo'
import { ProductCostType } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductQueryService } from '../../ProductQueryService'
import type { ProductCostOptionInput } from '../../../entities/ProductCost'
import type {
	ParseContext,
	ParsedProductCostRow,
	ProductCostBuildInput,
	ProductCostCsvParseResult,
	ProductCostCsvProcessor,
	ProductCostCsvRowError,
} from '../types'

/**
 * Groups Shopify rows by handle, bulk-resolves (handle → product + variants by
 * title) via ProductQueryService, and emits one SINGLE-cost build per resolved
 * product. Unknown handle / blank or unmatched variant name → typed skip rows.
 */
@injectable()
export class ShopifyProductCostCsvProcessor implements ProductCostCsvProcessor {
	constructor(private readonly products: ProductQueryService) {}

	async process(rows: ParsedProductCostRow[], ctx: ParseContext): Promise<ProductCostCsvParseResult> {
		const errors: ProductCostCsvRowError[] = []
		const byHandle = new Map<string, ParsedProductCostRow[]>()
		for (const r of rows) {
			const list = byHandle.get(r.handle!) ?? []
			list.push(r)
			byHandle.set(r.handle!, list)
		}

		const resolved = await this.products.resolveProductsWithVariantsByHandles(ctx.storeIntegrationId, [...byHandle.keys()])
		const byHandleResolved = new Map(resolved.map(p => [p.handle, p]))

		const builds: ProductCostBuildInput[] = []
		for (const [handle, handleRows] of byHandle) {
			const product = byHandleResolved.get(handle)
			if (!product) {
				for (const r of handleRows) errors.push({ row: r.row, code: 'CSV_UNKNOWN_HANDLE', value: handle })
				continue
			}
			const variantByTitle = new Map(product.variants.map(v => [v.title, v.variantId]))
			const items: ProductCostOptionInput['items'] = []
			const sourceRows: number[] = []
			for (const r of handleRows) {
				if (!r.variantName) {
					errors.push({ row: r.row, code: 'CSV_BLANK_VARIANT_NAME', value: handle })
					continue
				}
				const variantId = variantByTitle.get(r.variantName)
				if (!variantId) {
					errors.push({ row: r.row, code: 'CSV_UNRESOLVED_VARIANT', value: r.variantName })
					continue
				}
				items.push({
					variantIds: [variantId],
					quantity: r.quantity,
					quantityModifier: r.quantityModifier,
					unitCost: r.unitCost,
				})
				sourceRows.push(r.row)
			}
			if (items.length === 0) continue
			const first = handleRows[0]!
			builds.push({
				productId: product.productId,
				costType: ProductCostType.SINGLE,
				options: [
					{
						currency: first.currency,
						startDate: first.startDate,
						endDate: first.endDate,
						items,
					},
				],
				sourceRows,
			})
		}

		return { builds, errors }
	}
}

import { injectable } from 'tsyringe-neo'
import { EventHandler } from '@bk-dash/core-typescript'
import { OrderUpdatedEvent } from '@bk-dash/contracts-typescript/wire/events'
import { NotificationCategory } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreIntegrationRepository } from '../../integration/repositories/StoreIntegrationRepository'
import { StoreMembershipRepository } from '../../tenancy/repositories/StoreMembershipRepository'
import { SendNotification } from '../usecases/SendNotification'

/**
 * External handler subscribing to the Go-published
 * `integration.shared.order.updated` event. Fans out an
 * ORDER_RECEIVED push to every member of the store the first time
 * this `(platform, externalId)` is seen (`isNew=true`). Subsequent
 * status updates (paid → refunded → etc.) don't re-push.
 *
 * Resolves recipients via Integration's `findByPlatformAndExternalId`
 * (storeIntegrationExternalId → storeId) + Tenancy's `findByStoreId`
 * (storeId → memberships). Drops silently when the integration or
 * its store has no members.
 *
 * Store-level opt-in toggle is a future iter; for now every member
 * receives the push.
 */
@injectable()
export class OrderUpdatedNotifyHandler extends EventHandler<typeof OrderUpdatedEvent> {
	readonly event = OrderUpdatedEvent

	constructor(
		private readonly storeIntegrationRepo: StoreIntegrationRepository,
		private readonly memberships: StoreMembershipRepository,
		private readonly sendNotification: SendNotification,
	) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		if (!event.payload.isNew) return

		const integration = await this.storeIntegrationRepo.findByPlatformAndExternalId(
			event.payload.platform,
			event.payload.storeIntegrationExternalId,
		)
		if (integration === undefined) return

		const members = await this.memberships.findByStoreId(integration.storeId.value)
		const targetUserIds = members.map(m => m.userId.value)
		if (targetUserIds.length === 0) return

		const amount = (event.payload.totalCents / 100).toFixed(2)
		await this.sendNotification.execute({
			userId: integration.ownerId.value,
			storeId: integration.storeId.value,
			targetUserIds,
			title: `New order: ${amount} ${event.payload.currency}`,
			content: `Order ${event.payload.externalId} (${event.payload.paymentStatus})`,
			category: NotificationCategory.ORDER_RECEIVED,
			important: false,
			pushEnabled: true,
			emailEnabled: false,
			contentType: 'text/plain',
			payload: {
				platform: event.payload.platform,
				orderExternalId: event.payload.externalId,
				storeIntegrationExternalId: event.payload.storeIntegrationExternalId,
				totalCents: event.payload.totalCents,
				currency: event.payload.currency,
				paymentStatus: event.payload.paymentStatus,
			},
		})
	}
}

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import { PlatformSchema, type PlatformProps } from '@integration/services'
import {
	CheckoutPlatform,
	InfoproductPlatform,
	MarketingPlatform,
	PaymentGateway,
	SalesPlatform,
	StoreIntegrationType,
} from '@bk-dash/contracts-typescript/wire/enums'
import Z from 'zod'
import type { IntegrationDomainErrors } from '../errors'

const StoreIntegrationSchema = z.object({
	storeId: z.instance(Id),
	type: z.enum(StoreIntegrationType),
	platform: z.union([
		z.enum(SalesPlatform),
		z.enum(CheckoutPlatform),
		z.enum(PaymentGateway),
		z.enum(MarketingPlatform),
		z.enum(InfoproductPlatform),
	]),
	externalId: z.string(),
	displayName: z.string().min(1).max(120),
	credentialSecretId: z.instance(Id).nullable(),
	active: z.boolean(),
	connectedAt: z.date(),
	disconnectedAt: z.date().nullable(),
	ownerId: z.instance(Id),
})

export type StoreIntegrationProps = Z.infer<typeof StoreIntegrationSchema>

/**
 * `StoreIntegration` aggregate per spec § 4 BC3. Lifecycle:
 *
 *   create → active (the handshake is cleared before create) → disconnect → disconnected
 *
 * Operational telemetry (last sync, last handshake, validity) is NOT held on the
 * aggregate: the emitted events are its record (logs + downstream consumers), so
 * the write model doesn't duplicate what the event stream already states.
 *
 * The `id` is deterministic via `StoreIntegration.deterministicId(platform,
 * externalId)`. Re-creating with the same (type, platform, externalId) tuple
 * yields the same id — webhook idempotency relies on it.
 */
export class StoreIntegration extends AggregateRoot<typeof StoreIntegrationSchema> {
	static override schema = StoreIntegrationSchema

	static deterministicId(platform: PlatformProps, externalId: string): Id {
		return Id.fromSeed('integration', `${platform.type}:${platform.platform}`, externalId)
	}

	static create(data: {
		storeId: string
		platform: PlatformProps
		externalId: string
		displayName: string
		ownerId: string
	}): StoreIntegration {
		// Validate the discriminated platform shape before deriving the id.
		PlatformSchema.parse(data.platform)

		const id = StoreIntegration.deterministicId(data.platform, data.externalId)
		return new StoreIntegration({
			id,
			storeId: data.storeId,
			type: data.platform.type,
			platform: data.platform.platform,
			externalId: data.externalId,
			displayName: data.displayName,
			credentialSecretId: null,
			// Born active: ConnectIntegration only reaches create once the handshake
			// has already cleared, so there is no pending/invalid state to model.
			active: true,
			connectedAt: new Date(),
			disconnectedAt: null,
			ownerId: data.ownerId,
		})
	}

	/** Attach the freshly-saved credential-secret row. Called after CredentialVault.seal + save. */
	attachCredentialSecret(secretId: string): void {
		this.credentialSecretId = new Id(secretId)
		this.validate()
	}

	/** User-initiated disconnect. Terminal — STORE_INTEGRATION_ALREADY_DISCONNECTED on retry. */
	disconnect(): void {
		if (this.disconnectedAt) {
			throw new BaseError<IntegrationDomainErrors>('STORE_INTEGRATION_ALREADY_DISCONNECTED')
		}
		this.disconnectedAt = new Date()
		this.active = false
		this.validate()
	}

	/** Soft toggle. Used by admin overrides + reintegration flows. */
	toggleActive(active: boolean): void {
		this.active = active
		this.validate()
	}
}

export interface StoreIntegration extends StoreIntegrationProps {}

