import { injectable } from 'tsyringe-neo'
import { eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { orders } from '@bk-dash/contracts/db'
import { OrderSamplingService } from '../../tenancy/services/OrderSamplingService'

/**
 * Real implementation of Tenancy's cross-BC OrderSamplingService
 * port. Sales owns `sales.orders` — this adapter lives inside the
 * Sales BC and is bound via sales/registry.ts (overrides tenancy's
 * Mock binding via load order: tenancy registers first; sales's
 * later entry wins).
 *
 * `hasOrdersForStore` is used by Tenancy's UpdateStorePreferences
 * (C14) to gate the REPORTING_CURRENCY_LOCKED invariant — once a
 * store has any orders, currency cannot be re-pointed because
 * historical analytics rollups would lose their rate context.
 *
 * Single-row LIMIT 1 SELECT is the cheap "exists" check; no need to
 * count.
 */
@injectable()
export class SalesOrderSamplingService extends OrderSamplingService {
	constructor(private db: DrizzleClient) {
		super()
	}

	async hasOrdersForStore(storeId: string): Promise<boolean> {
		const result = await tryCatchAsync(async () => {
			const rows = await this.db.select({ id: orders.id }).from(orders).where(eq(orders.storeId, storeId)).limit(1)
			return rows.length > 0
		})
		if (!result.success) throw result.error
		return result.data
	}
}

