import { injectable } from 'tsyringe-neo'
import type { Transaction } from '@bk-dash/core-typescript'
import { StoreIntegration } from '../../entities/StoreIntegration'
import type { PlatformProps } from '@integration/services'
import { StoreIntegrationRepository } from './StoreIntegrationRepository'

@injectable()
export class MockStoreIntegrationRepository extends StoreIntegrationRepository {
	private rows = new Map<string, StoreIntegration>()

	async findById(id: string, _tx?: Transaction): Promise<StoreIntegration | undefined> {
		return this.rows.get(id)
	}

	async findByStoreId(storeId: string, _tx?: Transaction): Promise<StoreIntegration[]> {
		const out: StoreIntegration[] = []
		for (const row of this.rows.values()) {
			if (row.storeId.value === storeId) out.push(row)
		}
		return out
	}

	async findByStoreIdAndPlatform(storeId: string, platform: PlatformProps, _tx?: Transaction): Promise<StoreIntegration | undefined> {
		for (const row of this.rows.values()) {
			if (row.storeId.value === storeId && row.type === platform.type && row.platform === platform.platform) {
				return row
			}
		}
		return undefined
	}

	async findByPlatformAndExternalId(platform: string, externalId: string, _tx?: Transaction): Promise<StoreIntegration | undefined> {
		for (const row of this.rows.values()) {
			if (row.platform === platform && row.externalId === externalId) {
				return row
			}
		}
		return undefined
	}

	async findByExternalId(externalId: string, _tx?: Transaction): Promise<StoreIntegration | null> {
		for (const row of this.rows.values()) {
			if (row.externalId === externalId) return row
		}
		return null
	}

	async save(entity: StoreIntegration, _tx?: Transaction): Promise<StoreIntegration> {
		this.rows.set(entity.id.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		this.rows.delete(id)
	}

	seed(integration: StoreIntegration): void {
		this.rows.set(integration.id.value, integration)
	}

	clear(): void {
		this.rows.clear()
	}
}

