import { injectable } from 'tsyringe-neo'
import { EventHandler, Id, type Transaction } from '@bk-dash/core-typescript'
import { OrderUpdatedEvent } from '@bk-dash/contracts-typescript/wire/events'
import { ProductCostSolver } from '../../services/ProductCostSolver'
import { ProductCostLineAllocator } from '../../services/ProductCostLineAllocator'
import { ProductCostQueryService } from '../../../catalog/services/ProductCostQueryService'
import { OrderOverride } from '../../entities/OrderOverride'
import { OrderOverrideRepository } from '../../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderQueryService, type OrderLineDTO } from '../../services/OrderQueryService'

type OrderQueryResult = Awaited<ReturnType<OrderQueryService['findById']>>

@injectable()
export class ProductCostApplicationHandler extends EventHandler<typeof OrderUpdatedEvent> {
	readonly event = OrderUpdatedEvent
	private readonly allocator = new ProductCostLineAllocator()

	constructor(
		private readonly orderQuery: OrderQueryService,
		private readonly costQuery: ProductCostQueryService,
		private readonly overrideRepo: OrderOverrideRepository,
	) {
		super()
	}

	async handle(event: this['input'], tx?: Transaction): Promise<void> {
		const { platform, externalId } = event.payload
		const orderId = Id.fromSeed('order', platform, externalId).value
		const order = await this.orderQuery.findById(orderId)
		if (!order) return
		await this.applyForOrder(order, tx)
	}

	private async applyForOrder(order: NonNullable<OrderQueryResult>, tx?: Transaction): Promise<void> {
		const lines: OrderLineDTO[] = order.lines
		if (lines.length === 0) return

		const variantProducts = new Map<string, string>()
		const variantQuantities = new Map<string, number>()
		const guardedLines: Array<{ id: string; productId: string; variantId: string; quantity: number }> = []
		for (const line of lines) {
			if (!line.variantId || !line.productId) continue
			variantProducts.set(line.variantId, line.productId)
			variantQuantities.set(line.variantId, (variantQuantities.get(line.variantId) ?? 0) + line.quantity)
			guardedLines.push({ id: line.id, productId: line.productId, variantId: line.variantId, quantity: line.quantity })
		}
		if (variantQuantities.size === 0) return

		const productIds = Array.from(new Set(variantProducts.values()))
		const costs = await this.costQuery.findApplicable({ storeId: order.storeId, productIds, at: order.externalCreatedAt })

		const solved = new ProductCostSolver({ costs, variantProducts, variants: variantQuantities }).solve()
		const productCostByLine = this.allocator.allocate(
			solved,
			guardedLines.map(l => ({ id: l.id, productId: l.productId, quantity: l.quantity })),
		)

		let override = await this.overrideRepo.findByPin(order.id, order.storeIntegrationExternalId, tx)
		if (!override) {
			override = OrderOverride.create({
				storeId: order.storeId,
				orderId: order.id,
				storeIntegrationExternalId: order.storeIntegrationExternalId,
				fields: {},
			})
		}
		override.setProductCostByLine(productCostByLine)
		await this.overrideRepo.save(override, tx)
	}
}

import type { ApplicableProductCost } from './ApplicableProductCost'

export interface FindApplicableProductCostsInput {
	storeId: string
	/** Canonical product UUIDs present on the order. When omitted, all store costs are returned. */
	productIds?: string[]
	/** Order date used to filter costs by their effective interval. */
	at?: Date
}

/**
 * Cross-BC read port: surfaces catalog cost rules in the solver's
 * `ApplicableProductCost` shape so the sales-side ProductCostApplicationHandler
 * can resolve per-line costs without depending on catalog internals.
 * (Naming + Zod-return convention per feedback_query_service_naming_and_zod.)
 */
export abstract class ProductCostQueryService {
	abstract findApplicable(input: FindApplicableProductCostsInput): Promise<ApplicableProductCost[]>
}

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { OrderOverrideFieldsSchema, type OrderOverrideFieldsInput } from '../objects/OrderOverrideFields'
import type { SalesDomainErrors } from '../errors'

export const OrderOverrideSchema = z.object({
	storeId: z.instance(Id),
	orderId: z.instance(Id),
	storeIntegrationExternalId: z.string(),
	fields: OrderOverrideFieldsSchema,
})

export type OrderOverrideProps = Z.infer<typeof OrderOverrideSchema>

/**
 * Deterministic id for an OrderOverride. The natural key is
 * (orderId, storeIntegrationExternalId) — the same pair that pins the
 * row in `order_overrides`. Deriving the entity id from that key keeps
 * id stable across read-rehydrate cycles even when the table doesn't
 * carry a surrogate UUID column.
 */
export function orderOverrideId(orderId: string, storeIntegrationExternalId: string): string {
	return Id.fromSeed('order_override', orderId, storeIntegrationExternalId).value
}

export class OrderOverride extends AggregateRoot<typeof OrderOverrideSchema> {
	static override schema = OrderOverrideSchema

	static create(data: {
		storeId: string
		orderId: string
		storeIntegrationExternalId: string
		fields: OrderOverrideFieldsInput
	}): OrderOverride {
		const parsed = OrderOverrideFieldsSchema.safeParse(data.fields)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		return new OrderOverride({
			id: orderOverrideId(data.orderId, data.storeIntegrationExternalId),
			...data,
			fields: parsed.data,
		})
	}

	mergeFields(patch: OrderOverrideFieldsInput): void {
		const parsed = OrderOverrideFieldsSchema.safeParse(patch)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		this.fields = { ...this.fields, ...parsed.data }
	}

	/** Replace the resolved per-line product cost (SPEC-11 ProductCostApplicationHandler output). */
	setProductCostByLine(byLine: NonNullable<OrderOverrideFieldsInput['productCostByLine']>): void {
		const next = { ...this.fields, productCostByLine: byLine }
		const parsed = OrderOverrideFieldsSchema.safeParse(next)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		this.fields = parsed.data
	}
}

export interface OrderOverride extends OrderOverrideProps {}

