import { injectable } from 'tsyringe-neo'
import { and, eq, inArray } from 'drizzle-orm'
import { DrizzleClient } from '@bk-dash/core-typescript'
import { products, productOverrides, variants } from '@bk-dash/contracts/db'
import { ProductStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductQueryService, type ProductQueryDTO, type ResolvedProductWithVariants } from './ProductQueryService'

@injectable()
export class DrizzleProductQueryService extends ProductQueryService {
	constructor(private readonly db: DrizzleClient) {
		super()
	}

	async findById(productId: string): Promise<ProductQueryDTO | null> {
		const rows = await this.db
			.select({
				id: products.id,
				storeIntegrationExternalId: products.storeIntegrationExternalId,
				platform: products.platform,
				externalId: products.externalId,
				title: products.title,
				handle: products.handle,
				status: products.status,
				externalCreatedAt: products.externalCreatedAt,
				tags: productOverrides.tags,
			})
			.from(products)
			.leftJoin(productOverrides, eq(productOverrides.productId, products.id))
			.where(eq(products.id, productId))
			.limit(1)

		if (rows.length === 0) return null
		return this.mapRow(rows[0]!)
	}

	async findByIds(productIds: string[]): Promise<ProductQueryDTO[]> {
		if (productIds.length === 0) return []
		const rows = await this.db
			.select({
				id: products.id,
				storeIntegrationExternalId: products.storeIntegrationExternalId,
				platform: products.platform,
				externalId: products.externalId,
				title: products.title,
				handle: products.handle,
				status: products.status,
				externalCreatedAt: products.externalCreatedAt,
				tags: productOverrides.tags,
			})
			.from(products)
			.leftJoin(productOverrides, eq(productOverrides.productId, products.id))
			.where(inArray(products.id, productIds))

		return rows.map(r => this.mapRow(r))
	}

	async resolveProductsWithVariantsByHandles(storeIntegrationExternalId: string, handles: string[]): Promise<ResolvedProductWithVariants[]> {
		if (handles.length === 0) return []
		const prodRows = await this.db
			.select({ id: products.id, handle: products.handle })
			.from(products)
			.where(and(eq(products.storeIntegrationExternalId, storeIntegrationExternalId), inArray(products.handle, handles)))
		const resolvable = prodRows.filter((p): p is { id: string; handle: string } => p.handle !== null)
		if (resolvable.length === 0) return []

		const productIds = resolvable.map(p => p.id)
		const variantRows = await this.db
			.select({ productId: variants.productId, id: variants.id, title: variants.title })
			.from(variants)
			.where(and(eq(variants.storeIntegrationExternalId, storeIntegrationExternalId), inArray(variants.productId, productIds)))

		const byProduct = new Map<string, { title: string; variantId: string }[]>()
		for (const v of variantRows) {
			if (v.title === null) continue
			const list = byProduct.get(v.productId) ?? []
			list.push({ title: v.title, variantId: v.id })
			byProduct.set(v.productId, list)
		}

		return resolvable.map(p => ({ handle: p.handle, productId: p.id, variants: byProduct.get(p.id) ?? [] }))
	}

	private mapRow(row: {
		id: string
		storeIntegrationExternalId: string
		platform: string
		externalId: string
		title: string
		handle: string | null
		status: string
		externalCreatedAt: Date
		tags: unknown
	}): ProductQueryDTO {
		return {
