const STORE_INTEGRATION_ID = testId('store_integration', '1')
const STORE_INTEGRATION_EXTERNAL_ID = 'acme.myshopify.com'
const PRODUCT_ID = Id.fromSeed('product', 'SHOPIFY', 'prod-1').value
const PRODUCT_ID_2 = Id.fromSeed('product', 'SHOPIFY', 'prod-2').value

describe('DrizzleProductQueryService', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let service: DrizzleProductQueryService
	let db: any

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		db = testBed.resolve(DrizzleClient)
	})
	beforeEach(async () => {
		await testBed.reset()
		service = testBed.resolve(DrizzleProductQueryService)
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedProduct(id: string, externalId: string, overrideTags?: string[]): Promise<void> {
		await db.insert(products).values({
			id,
			storeIntegrationExternalId: STORE_INTEGRATION_EXTERNAL_ID,
			platform: 'SHOPIFY',
			externalId,
			title: `Product ${externalId}`,
			handle: `product-${externalId}`,
			status: 'ACTIVE',
			externalCreatedAt: new Date('2026-01-01T00:00:00Z'),
		})
		if (overrideTags !== undefined) {
			await db.insert(productOverrides).values({
				id: Id.fromSeed('product_override', id, STORE_ID).value,
				productId: id,
				storeId: STORE_ID,
				tags: JSON.stringify(overrideTags),
			})
		}
	}

	it('findById returns null when product does not exist', async () => {
		const result = await service.findById('00000000-0000-0000-0000-000000000000')
		expect(result).toBeNull()
	})

	it('findById returns the product with its tags from productOverrides', async () => {
		await seedProduct(PRODUCT_ID, 'prod-1', ['bestseller'])
		const result = await service.findById(PRODUCT_ID)
		expect(result).not.toBeNull()
		expect(result!.id).toBe(PRODUCT_ID)
		expect(result!.storeIntegrationExternalId).toBe(STORE_INTEGRATION_EXTERNAL_ID)
		expect(result!.title).toBe('Product prod-1')
		expect(result!.handle).toBe('product-prod-1')
		expect(result!.status).toBe(ProductStatus.ACTIVE)
		expect(result!.tags).toEqual(['bestseller'])
	})

	it('findById returns empty tags when no override exists', async () => {
		await seedProduct(PRODUCT_ID, 'prod-1')
		const result = await service.findById(PRODUCT_ID)
		expect(result!.tags).toEqual([])
	})

	it('findByIds returns all matching products', async () => {
		await seedProduct(PRODUCT_ID, 'prod-1', ['a'])
		await seedProduct(PRODUCT_ID_2, 'prod-2', ['b'])
		const results = await service.findByIds([PRODUCT_ID, PRODUCT_ID_2])
		expect(results).toHaveLength(2)
		const ids = results.map(p => p.id)
		expect(ids).toContain(PRODUCT_ID)
		expect(ids).toContain(PRODUCT_ID_2)
	})

	it('findByIds with empty array returns empty array', async () => {
		const results = await service.findByIds([])
		expect(results).toEqual([])
	})

	async function seedVariant(id: string, productId: string, externalId: string, title: string): Promise<void> {
		await db.insert(variants).values({
			id,
			productId,
			storeIntegrationId: STORE_INTEGRATION_ID,
			storeIntegrationExternalId: 'acme.myshopify.com',
			platform: 'SHOPIFY',
			externalId,
			productExternalId: 'prod-1',
			title,
			status: 'ACTIVE',
			externalCreatedAt: new Date('2026-01-01T00:00:00Z'),
		})
	}

	it('resolveProductsWithVariantsByHandles maps handle → product + variants by title', async () => {
		await seedProduct(PRODUCT_ID, 'prod-1')
		await seedVariant(Id.fromSeed('variant', 'SHOPIFY', 'v1').value, PRODUCT_ID, 'v1', 'Black / M')
		await seedVariant(Id.fromSeed('variant', 'SHOPIFY', 'v2').value, PRODUCT_ID, 'v2', 'Black / L')

		const result = await service.resolveProductsWithVariantsByHandles(STORE_INTEGRATION_ID, ['product-prod-1'])
		expect(result).toHaveLength(1)
		expect(result[0]!.productId).toBe(PRODUCT_ID)
		expect(result[0]!.handle).toBe('product-prod-1')
		const titles = result[0]!.variants.map(v => v.title).sort()
		expect(titles).toEqual(['Black / L', 'Black / M'])
	})

	it('resolveProductsWithVariantsByHandles returns [] for unknown handles + [] input', async () => {
		expect(await service.resolveProductsWithVariantsByHandles(STORE_INTEGRATION_ID, [])).toEqual([])
		expect(await service.resolveProductsWithVariantsByHandles(STORE_INTEGRATION_ID, ['nope'])).toEqual([])
	})
})

