import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { Id } from '@bk-dash/core-typescript'
import { CurrencyCode, PaymentStatus, ProductCostType, QuantityModifier, SalesPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { OrderUpdatedEvent } from '@bk-dash/contracts-typescript/wire/events'
import { ProductCostApplicationHandler } from './ProductCostApplicationHandler'
import { OrderOverrideRepository } from '../../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { ProductCostQueryService, MockProductCostQueryService } from '../../../catalog/services/ProductCostQueryService'
import { OrderQueryService, MockOrderQueryService } from '../../services/OrderQueryService'

const STORE = testId('store', '1')
const SI_EXTERNAL = 'acme.myshopify.com'
const PLATFORM = SalesPlatform.SHOPIFY
const ORDER_EXTERNAL = 'shopify_order_1'
const PRODUCT_ID = Id.fromSeed('product', PLATFORM, 'shopify_prod_1').value
const VARIANT_ID = Id.fromSeed('product_variant', PLATFORM, 'shopify_var_1').value
const ORDER_ID = Id.fromSeed('order', PLATFORM, ORDER_EXTERNAL).value

/** Minimal order shape matching what OrderQueryService.findById returns. */
function makeOrder(quantity: number) {
	return {
		id: ORDER_ID,
		storeId: STORE,
		storeIntegrationExternalId: SI_EXTERNAL,
		externalCreatedAt: new Date('2026-05-01T10:00:00Z'),
		lines: [{ id: 'line-1', productId: PRODUCT_ID, variantId: VARIANT_ID, quantity }],
	}
}

describe('ProductCostApplicationHandler (SPEC-12)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let handler: ProductCostApplicationHandler
	let overrideRepo: OrderOverrideRepository
	let costQuery: MockProductCostQueryService
	let orderQuery: MockOrderQueryService

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		// Mock query services fed test data via the sanctioned escape hatch (no cast).
		// integration mode binds the Drizzle impls by default; these replace them so the
		// handler runs without DB reads for orders/costs. State reset per test below.
		costQuery = new MockProductCostQueryService()
		orderQuery = new MockOrderQueryService()
		testBed.override(ProductCostQueryService, costQuery)
		testBed.override(OrderQueryService, orderQuery)
		handler = testBed.resolve(ProductCostApplicationHandler)
		overrideRepo = testBed.resolve(OrderOverrideRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
		// Reset mock state so each test starts with empty order/cost feeds.
		costQuery.nextCosts = []
		orderQuery.nextOrders = []
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function orderUpdatedEvent(): OrderUpdatedEvent {
		return new OrderUpdatedEvent({
			ownerId: STORE,
			payload: {
				platform: PLATFORM,
				externalId: ORDER_EXTERNAL,
				storeIntegrationExternalId: SI_EXTERNAL,
				paymentStatus: PaymentStatus.PAID,
				totalCents: 0,
				currency: CurrencyCode.USD,
				isNew: true,
				entity: {},
			},
		})
	}

	it('OrderUpdated → resolves per-line cost via OrderQueryService + writes OrderOverride.productCostByLine', async () => {
		orderQuery.nextOrders = [makeOrder(2)]
		costQuery.nextCosts = [
			{
				costId: 'cost-1',
				costOptionId: 'opt-1',
				type: ProductCostType.SINGLE,
				startDate: new Date('2026-01-01'),
				endDate: null,
				productId: PRODUCT_ID,
				variants: [],
				data: [
					{
						cost: 500,
						costOptionItemId: 'item-1',
						currency: CurrencyCode.USD,
						productId: PRODUCT_ID,
						quantity: 1,
						quantityModifier: QuantityModifier.GTE,
						variants: [VARIANT_ID],
					},
				],
			},
		]

		await handler.handle(orderUpdatedEvent() as never)

		const override = await overrideRepo.findByPin(ORDER_ID, SI_EXTERNAL)
		expect(override).toBeDefined()
		const byLine = override!.fields.productCostByLine
		expect(byLine).toHaveLength(1)
		expect(byLine![0]!.lineId).toBe('line-1')
		// 2 units × 500 per unit → 1000 total for the line.
		expect(byLine![0]!.cost.amountCents).toBe(1000)
		expect(byLine![0]!.cost.currency).toBe(CurrencyCode.USD)
	})

	it('OrderUpdated with no matching cost → no per-line cost entries', async () => {
		orderQuery.nextOrders = [makeOrder(1)]
		costQuery.nextCosts = []

		await handler.handle(orderUpdatedEvent() as never)

		const override = await overrideRepo.findByPin(ORDER_ID, SI_EXTERNAL)
		expect(override?.fields.productCostByLine ?? []).toHaveLength(0)
	})

	it('is idempotent — replaying the same event yields the same per-line cost', async () => {
		orderQuery.nextOrders = [makeOrder(2)]
		costQuery.nextCosts = [
			{
				costId: 'cost-1',
				costOptionId: 'opt-1',
				type: ProductCostType.SINGLE,
				startDate: new Date('2026-01-01'),
				endDate: null,
				productId: PRODUCT_ID,
				variants: [],
				data: [
					{
						cost: 500,
						costOptionItemId: 'item-1',
						currency: CurrencyCode.USD,
						productId: PRODUCT_ID,
						quantity: 1,
						quantityModifier: QuantityModifier.GTE,
						variants: [VARIANT_ID],
					},
				],
			},
		]

		await handler.handle(orderUpdatedEvent() as never)
		await handler.handle(orderUpdatedEvent() as never)

		const override = await overrideRepo.findByPin(ORDER_ID, SI_EXTERNAL)
		expect(override!.fields.productCostByLine).toHaveLength(1)
		expect(override!.fields.productCostByLine![0]!.cost.amountCents).toBe(1000)
	})

	it('handler reads orders via OrderQueryService, not via Drizzle directly', () => {
		// Structural assertion: the handler class has no `db` property after the
		// constructor refactor. This catches a regression where DrizzleClient is
		// accidentally re-injected.
		const handlerInstance = handler as any
		expect(handlerInstance.db).toBeUndefined()
		// The orderQuery property must be the mock we registered.
		expect(handlerInstance.orderQuery).toBe(orderQuery)
	})
})

import { injectable } from 'tsyringe-neo'
import type { Transaction } from '@bk-dash/core-typescript'
import { StoreIntegration } from '../../entities/StoreIntegration'
import type { PlatformProps } from '@integration/services'
import { StoreIntegrationRepository } from './StoreIntegrationRepository'

@injectable()
export class MockStoreIntegrationRepository extends StoreIntegrationRepository {
	private rows = new Map<string, StoreIntegration>()

	async findById(id: string, _tx?: Transaction): Promise<StoreIntegration | undefined> {
		return this.rows.get(id)
	}

	async findByStoreId(storeId: string, _tx?: Transaction): Promise<StoreIntegration[]> {
		const out: StoreIntegration[] = []
		for (const row of this.rows.values()) {
			if (row.storeId.value === storeId) out.push(row)
		}
		return out
	}

	async findByStoreIdAndPlatform(storeId: string, platform: PlatformProps, _tx?: Transaction): Promise<StoreIntegration | undefined> {
		for (const row of this.rows.values()) {
			if (row.storeId.value === storeId && row.type === platform.type && row.platform === platform.platform) {
				return row
			}
		}
		return undefined
	}

	async findByPlatformAndExternalId(platform: string, externalId: string, _tx?: Transaction): Promise<StoreIntegration | undefined> {
		for (const row of this.rows.values()) {
			if (row.platform === platform && row.externalId === externalId) {
				return row
			}
		}
		return undefined
	}

	async findByExternalId(externalId: string, _tx?: Transaction): Promise<StoreIntegration | null> {
		for (const row of this.rows.values()) {
			if (row.externalId === externalId) return row
		}
		return null
	}

	async save(entity: StoreIntegration, _tx?: Transaction): Promise<StoreIntegration> {
		this.rows.set(entity.id.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		this.rows.delete(id)
	}

	seed(integration: StoreIntegration): void {
		this.rows.set(integration.id.value, integration)
	}

	clear(): void {
		this.rows.clear()
	}
}

